export const DEFAULT_UPGRADES = { tank: 0, lamp: 0, fins: 0, suit: 0, deco: 0 };

export function gearStats(up) {
  return {
    maxAir: 110 + up.tank * 35,
    lamp: 15 + up.lamp * 7,
    speed: 1 + up.fins * 0.12,
    absorb: 1 - up.suit * 0.18,
    offgas: 1 + up.deco * 0.22,
  };
}

export function upgradeCost(upg, level) {
  return Math.round((upg.baseCost * Math.pow(1.85, level)) / 10) * 10;
}

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const rand = (a, b) => a + Math.random() * (b - a);
const pick = (arr) => arr[(Math.random() * arr.length) | 0];

function lootValue(depth, r) {
  if (depth < 80) return Math.round((65 + r * 75) / 5) * 5;
  if (depth < 160) return Math.round((145 + r * 120) / 5) * 5;
  if (depth < 235) return Math.round((275 + r * 150) / 5) * 5;
  return Math.round((445 + r * 210) / 5) * 5;
}

function lootKind(depth) {
  if (depth < 80) return pick(['crate', 'crate', 'urn']);
  if (depth < 160) return pick(['crate', 'urn', 'barrel']);
  if (depth < 235) return pick(['barrel', 'urn', 'crate']);
  return pick(['barrel', 'urn', 'barrel']);
}

export function createRun(contractIndex, upgrades, opts = {}) {
  const contract = CONTRACTS[contractIndex];
  const stats = gearStats(upgrades);
  const maxD = opts.freeDive ? 300 : contract.depth;

  const run = {
    contractIndex,
    contract,
    freeDive: !!opts.freeDive,
    gear: stats,
    time: 0,
    depth: 1.2,
    x: 60,
    vx: 0,
    vy: 0,
    air: stats.maxAir,
    maxAir: stats.maxAir,
    n2: 0,
    bends: 0,
    cargo: 0,
    quota: contract.quota,
    special: !!contract.special,
    specialDone: !contract.special,
    items: [],
    canisters: [],
    jellies: [],
    currents: [],
    fish: [],
    vents: [],
    particles: [],
    texts: [],
    camera: { x: 60, y: 20, shake: 0 },
    invuln: 0,
    dead: false,
    deathCause: '',
    timeAlive: 0,
    peakDepth: 1.2,
    lastDepth: 1.2,
    ascentRate: 0,
    offgassing: false,
    ongassing: false,
    atSurface: false,
    quotaMet: false,
    tips: {},
    surfaced: false,
    surfaceReady: false,
    pickups: 0,
    canisterCount: 0,
    flash: 0,
    bubbles: [],
    lampFlicker: 1,
  };

  // ---- salvage ----
  const count = opts.freeDive ? 26 : 24;
  const used = [];
  for (let i = 0; i < count; i++) {
    let d = 0;
    for (let tries = 0; tries < 20; tries++) {
      // Bias slightly deep so descending is rewarded.
      d = 14 + Math.pow(Math.random(), 0.72) * (maxD - 14);
      if (used.every((u) => Math.abs(u - d) > 7)) break;
    }
    used.push(d);
    run.items.push({
      id: `loot${i}`,
      x: rand(20, 100),
      depth: Math.round(d * 10) / 10,
      value: lootValue(d, Math.random()),
      kind: lootKind(d),
      phase: rand(0, Math.PI * 2),
      bob: rand(0, Math.PI * 2),
      taken: false,
      tier: d < 80 ? 0 : d < 160 ? 1 : d < 235 ? 2 : 3,
    });
  }

  // ---- air canisters (always worth finding) ----
  const canDepth = [0.32, 0.6, 0.82, 1.0];
  for (let i = 0; i < canDepth.length; i++) {
    run.canisters.push({
      x: rand(26, 94),
      depth: Math.max(18, Math.round(canDepth[i] * maxD + rand(-4, 4))),
      amount: 32,
      phase: rand(0, Math.PI * 2),
      taken: false,
    });
  }

  // ---- jellyfish ----
  const jellies = 6;
  for (let i = 0; i < jellies; i++) {
    const d = 26 + (i / (jellies - 1)) * (maxD - 26) + rand(-8, 8);
    run.jellies.push({
      x: rand(24, 96),
      baseX: 0,
      depth: clamp(d, 20, maxD + 6),
      phase: rand(0, Math.PI * 2),
      drift: rand(1.4, 3.2) * (Math.random() > 0.5 ? 1 : -1),
      size: rand(0.8, 1.35),
      bobAmp: rand(1.5, 4),
      bobSpeed: rand(0.4, 0.9),
      hit: false,
    });
  }
  for (const j of run.jellies) j.baseX = j.x;

  // ---- currents ----
  if (maxD > 90) {
    run.currents.push({
      depth: Math.round(maxD * 0.34), width: 13,
      force: (Math.random() > 0.5 ? 1 : -1) * 2.2, phase: rand(0, 6),
      strength: 1,
    });
    run.currents.push({
      depth: Math.round(maxD * 0.7), width: 12,
      force: (Math.random() > 0.5 ? 1 : -1) * 2.8, phase: rand(0, 6),
      strength: 1,
    });
  }

  // ---- decorative fish ----
  for (let i = 0; i < 26; i++) {
    run.fish.push({
      x: rand(0, WORLD.width),
      depth: rand(12, Math.max(40, maxD + 20)),
      speed: rand(1.2, 4.2) * (Math.random() > 0.5 ? 1 : -1),
      size: rand(0.5, 1.5),
      phase: rand(0, Math.PI * 2),
      wobble: rand(0.4, 1.4),
      deep: Math.random() > 0.78,
    });
  }

  // ---- vents ----
  for (let i = 0; i < 7; i++) {
    run.vents.push({
      x: rand(10, 110),
      depth: WORLD.floor - rand(1, 5),
      phase: rand(0, Math.PI * 2),
      rate: rand(0.4, 1.1),
    });
  }

  // ---- black box ----
  if (contract.special) {
    run.items.push({
      id: 'blackbox',
      x: 58,
      depth: 288,
      value: 1600,
      kind: 'blackbox',
      phase: 0,
      bob: 0,
      taken: false,
      tier: 4,
      special: true,
    });
  }

  return run;
}

export function updateRun(run, dt, input, events) {
  if (run.dead) return;
  const stats = run.gear;
  const contract = run.contract;
  run.time += dt;
  run.timeAlive += dt;

  // ---------- movement ----------
  let ix = input.x || 0;
  let iy = input.y || 0;
  const mag = Math.hypot(ix, iy);
  if (mag > 1) { ix /= mag; iy /= mag; }
  const boosting = !!input.boost && mag > 0.1 && run.air > 0 && run.depth > 0.9;
  const boostMul = boosting ? 1.42 : 1;

  const accel = 20 * stats.speed * boostMul;
  run.vx += ix * accel * dt;
  run.vy += iy * accel * dt;

  // gentle current push
  for (const c of run.currents) {
    if (Math.abs(run.depth - c.depth) < c.width / 2) {
      run.vx += c.force * dt * 1.25;
    }
  }

  // buoyancy: barely positive, keeps the diver floating when idle
  run.vy -= 0.12 * dt;

  const drag = Math.pow(0.0032, dt); // ≈ exp(-5.75 dt)
  run.vx *= drag;
  run.vy *= drag;

  const maxV = 5.7 * stats.speed * boostMul;
  const sp = Math.hypot(run.vx, run.vy);
  if (sp > maxV) { run.vx = (run.vx / sp) * maxV; run.vy = (run.vy / sp) * maxV; }

  run.x += run.vx * dt;
  const oldDepth = run.depth;
  run.depth += run.vy * dt;

  // bounds
  if (run.x < 4) { run.x = 4; run.vx = Math.max(0, run.vx); }
  if (run.x > WORLD.width - 4) { run.x = WORLD.width - 4; run.vx = Math.min(0, run.vx); }
  if (run.depth < 0.8) {
    run.depth = 0.8;
    if (run.vy < 0) run.vy = 0;
    if (oldDepth > 2) events.push({ type: 'surface' });
  }
  if (run.depth > WORLD.floor - 2) {
    run.depth = WORLD.floor - 2;
    if (run.vy > 0) run.vy = 0;
  }

  run.ascentRate = (run.depth - oldDepth) / Math.max(dt, 0.0001); // negative = up
  run.peakDepth = Math.max(run.peakDepth, run.depth);
  run.atSurface = run.depth < 2.2;
  run.invuln = Math.max(0, run.invuln - dt);
  run.flash = Math.max(0, run.flash - dt * 3);

  // ---------- nitrogen model ----------
  // Ceiling = the shallowest depth the body can tolerate right now.
  const ceiling = Math.max(0, (run.n2 - 7) * 3.2);
  run.ceiling = ceiling;
  const depthAboveCeiling = ceilDelta(run.depth, ceiling);

  run.offgassing = false;
  run.ongassing = false;
  run.aboveCeiling = false;

  if (run.depth > 0.9) {
    if (depthAboveCeiling > 0.6) {
      // staying deep loads tissue
      if (run.vy > -0.35) {
        const absorb = (0.38 + run.depth * 0.0042) * stats.absorb;
        run.n2 = clamp(run.n2 + absorb * dt, 0, 100);
        run.ongassing = true;
      }
    } else if (run.depth >= ceiling - 1.6) {
      // at the ceiling: vent nitrogen
      const rate = 1.18 * stats.offgas;
      run.n2 = Math.max(0, run.n2 - rate * dt);
      run.offgassing = true;
    } else {
      // above the ceiling: bubbles form
      run.aboveCeiling = true;
      const over = ceiling - run.depth;
      run.bends = clamp(run.bends + over * 0.82 * dt, 0, 100);
      run.camera.shake = Math.max(run.camera.shake, Math.min(1, over / 25 + 0.2));
      events.push({ type: 'aboveCeiling', over });
    }
  }
  if (!run.aboveCeiling) {
    run.bends = Math.max(0, run.bends - 1.15 * dt);
  }

  // ---------- air ----------
  if (run.depth > 0.9) {
    const speedRatio = Math.min(1, Math.hypot(run.vx, run.vy) / 6);
    let drain = (0.185 + run.depth * 0.00225) * (1 + 0.62 * speedRatio);
    if (boosting) drain *= 1.55;
    run.air = Math.max(0, run.air - drain * dt);
    if (run.air <= 0) {
      run.dead = true;
      run.deathCause = 'OUT OF AIR';
      events.push({ type: 'death', cause: 'OUT OF AIR' });
      return;
    }
    if (run.air < run.maxAir * 0.22 && !run.tips.lowAir) {
      run.tips.lowAir = true;
      events.push({ type: 'lowAir' });
    }
    if (run.air > run.maxAir * 0.3) run.tips.lowAir = false;
  }
  if (run.bends >= 100) {
    run.dead = true;
    run.deathCause = 'DECOMPRESSION SICKNESS';
    events.push({ type: 'death', cause: 'DECOMPRESSION SICKNESS' });
    return;
  }

  // ---------- pickups ----------
  for (const it of run.items) {
    if (it.taken) continue;
    it.bob += dt;
    const radius = it.kind === 'blackbox' ? 4.2 : 3.0;
    if (Math.abs(it.depth - run.depth) < radius && Math.abs(it.x - run.x) < radius + 0.6) {
      it.taken = true;
      run.pickups++;
      run.cargo += it.value;
      if (it.special) {
        run.specialDone = true;
        run.flash = 0.9;
        events.push({ type: 'blackbox', value: it.value, x: it.x, depth: it.depth });
      } else {
        events.push({ type: 'loot', value: it.value, x: it.x, depth: it.depth });
      }
      run.bubbles.push({ x: it.x, depth: it.depth, life: 0.8, r: 0.5, vy: -2 });
    }
  }

  for (const c of run.canisters) {
    if (c.taken) continue;
    c.phase += dt;
    if (Math.abs(c.depth - run.depth) < 3.2 && Math.abs(c.x - run.x) < 3.4) {
      c.taken = true;
      const before = run.air;
      run.air = Math.min(run.maxAir, run.air + c.amount);
      run.canisterCount++;
      events.push({ type: 'air', amount: Math.round(run.air - before), x: c.x, depth: c.depth });
    }
  }

  // jellyfish
  for (const j of run.jellies) {
    j.phase += dt;
    j.x = j.baseX + Math.sin(j.phase * 0.55 + j.drift) * 5.5;
    j.x = clamp(j.x, 8, WORLD.width - 8);
    const jd = j.depth + Math.sin(j.phase * j.bobSpeed + 1.3) * j.bobAmp;
    j.renderDepth = jd;
    if (run.invuln <= 0) {
      const dx = j.x - run.x;
      const dd = jd - run.depth;
      const hitR = 2.3 * j.size + 0.9;
      if (dx * dx + dd * dd < hitR * hitR) {
        run.invuln = 2.2;
        run.air = Math.max(0, run.air - 7);
        run.bends = clamp(run.bends + 7, 0, 100);
        run.flash = 0.8;
        run.camera.shake = 1;
        run.vx += (run.x - j.x) * 1.5;
        run.vy += (run.depth - jd) * 1.2;
        events.push({ type: 'sting', x: j.x, depth: jd });
      }
    }
  }

  // decorative fish
  for (const f of run.fish) {
    f.x += f.speed * dt;
    if (f.x < -4) f.x = WORLD.width + 4;
    if (f.x > WORLD.width + 4) f.x = -4;
    f.phase += dt * f.wobble;
  }

  // ---------- ambient particles (marine snow) ----------
  if (run.particles.length < 90) {
    for (let i = run.particles.length; i < 90; i++) {
      run.particles.push({
        x: Math.random() * WORLD.width,
        depth: Math.random() * (run.depth + 50),
        vx: rand(-0.25, 0.25),
        vy: rand(0.18, 0.7),
        r: rand(0.06, 0.22),
        glow: Math.random() > 0.78,
        a: rand(0.15, 0.7),
      });
    }
  }
  for (const p of run.particles) {
    p.depth += p.vy * dt;
    p.x += p.vx * dt;
    if (p.x < 0) p.x += WORLD.width;
    if (p.x > WORLD.width) p.x -= WORLD.width;
    if (p.depth > WORLD.floor + 4) {
      p.depth = Math.random() * (run.depth - 6);
      p.x = Math.random() * WORLD.width;
    }
  }

  // floating pickup text
  for (let i = run.texts.length - 1; i >= 0; i--) {
    const t = run.texts[i];
    t.life -= dt;
    t.depth -= dt * 1.4;
    if (t.life <= 0) run.texts.splice(i, 1);
  }

  // diver exhaust bubbles
  if (Math.random() < dt * (boosting ? 26 : 12)) {
    run.bubbles.push({
      x: run.x + rand(-0.4, 0.4),
      depth: run.depth - 0.8,
      life: rand(1.2, 2.4),
      r: rand(0.1, 0.32),
      vy: rand(-2.2, -1.2),
    });
  }
  for (let i = run.bubbles.length - 1; i >= 0; i--) {
    const b = run.bubbles[i];
    b.life -= dt;
    b.depth += b.vy * dt;
    b.x += Math.sin(run.time * 5 + i) * dt * 0.3;
    if (b.life <= 0 || b.depth < 0) run.bubbles.splice(i, 1);
  }

  // ---------- camera ----------
  const targetY = clamp(
    run.depth + (run.vy > 0 ? run.vy * 0.45 : run.vy * 0.3) - 2,
    17,
    WORLD.floor + 2
  );
  run.camera.y += (targetY - run.camera.y) * Math.min(1, dt * 3.4);
  run.camera.x += (run.x - run.camera.x) * Math.min(1, dt * 4.2);
  run.camera.shake = Math.max(0, run.camera.shake - dt * 1.8);

  // quota + surface readiness
  run.quotaMet = run.cargo >= run.quota;
  run.surfaceReady = run.atSurface && run.quotaMet && run.specialDone;
}

function ceilDelta(depth, ceiling) {
  // positive when depth is below the ceiling line (safe side)
  return depth - ceiling;
}

export function canSurface(run) {
  return run.depth < 2.4;
}

export function surfaceOutcome(run) {
  return {
    ok: run.quotaMet && run.specialDone,
    quotaMet: run.quotaMet,
    specialDone: run.specialDone,
    bends: run.bends,
  };
}

// ============================================================
// DECOMP — procedural audio (WebAudio, no assets)
// ============================================================

export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.ambient = null;
    this.depth = 0;
    this.lastPing = 0;
    this.started = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    this.master.connect(this.ctx.destination);
    this._buildAmbient();
    this.started = true;
  }

  _buildAmbient() {
    const ctx = this.ctx;
    // ocean bed: filtered noise loop
    const len = ctx.sampleRate * 3;
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buf;
    noise.loop = true;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 380;
    lp.Q.value = 0.7;
    const ng = ctx.createGain();
    ng.gain.value = 0.22;
    noise.connect(lp).connect(ng).connect(this.master);
    noise.start();

    // deep drone
    const droneGain = ctx.createGain();
    droneGain.gain.value = 0.1;
    const dronep = ctx.createBiquadFilter();
    dronep.type = 'lowpass';
    dronep.frequency.value = 220;
    droneGain.connect(dronep).connect(this.master);
    const oscs = [];
    [41.2, 55, 82.4].forEach((f, i) => {
      const o = ctx.createOscillator();
      o.type = i === 2 ? 'triangle' : 'sine';
      o.frequency.value = f;
      const g = ctx.createGain();
      g.gain.value = i === 2 ? 0.06 : 0.5;
      o.connect(g).connect(droneGain);
      o.start();
      oscs.push(o);
    });

    // slow LFO on drone filter
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 70;
    lfo.connect(lfoGain).connect(dronep.frequency);
    lfo.start();

    this.ambient = { noise, lp, ng, droneGain, dronep, oscs };
  }

  setDepth(depth) {
    this.depth = depth;
    if (!this.ambient || !this.ctx) return;
    const t = this.ctx.currentTime;
    const f = Math.max(130, 460 - depth * 1.05);
    this.ambient.lp.frequency.setTargetAtTime(f, t, 1.2);
    this.ambient.dronep.frequency.setTargetAtTime(Math.max(90, 230 - depth * 0.5), t, 1.5);
    this.ambient.droneGain.gain.setTargetAtTime(0.075 + Math.min(0.12, depth / 2200), t, 1.5);
  }

  update(dt, depth) {
    if (!this.ctx) return;
    this.setDepth(depth);
    this.lastPing += dt;
    if (this.lastPing > 13 + Math.random() * 9 && depth > 30) {
      this.lastPing = 0;
      this.ping();
    }
  }

  _env(node, t0, a, d, peak) {
    node.gain.setValueAtTime(0.0001, t0);
    node.gain.exponentialRampToValueAtTime(peak, t0 + a);
    node.gain.exponentialRampToValueAtTime(0.0001, t0 + a + d);
  }

  tone(freq, dur, type = 'sine', vol = 0.12, slide = 0, delay = 0) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t0);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t0 + dur);
    this._env(g, t0, 0.008, dur, vol);
    o.connect(g).connect(this.master);
    o.start(t0);
    o.stop(t0 + dur + 0.05);
  }

  noiseBurst(dur, freq, vol = 0.1, delay = 0) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const len = Math.max(1, Math.floor(ctx.sampleRate * dur));
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = freq;
    f.Q.value = 1.1;
    const g = ctx.createGain();
    g.gain.value = vol;
    src.connect(f).connect(g).connect(this.master);
    src.start(t0);
  }

  click() { this.tone(520, 0.05, 'square', 0.05, -80); }
  hover() { this.tone(880, 0.03, 'sine', 0.025); }
  collect(value = 100) {
    const base = 620 + Math.min(400, value * 0.35);
    this.tone(base, 0.09, 'triangle', 0.1);
    this.tone(base * 1.5, 0.13, 'sine', 0.08, 0, 0.055);
    this.noiseBurst(0.05, 2600, 0.03);
  }
  air() {
    this.noiseBurst(0.35, 1400, 0.12);
    this.tone(330, 0.18, 'sine', 0.07, 220);
    this.tone(660, 0.22, 'sine', 0.05, 120, 0.08);
  }
  sting() {
    this.tone(140, 0.3, 'sawtooth', 0.12, -70);
    this.noiseBurst(0.2, 700, 0.15);
    this.tone(90, 0.4, 'square', 0.05, -30);
  }
  alarm() { this.tone(880, 0.1, 'square', 0.06); this.tone(660, 0.14, 'square', 0.05, 0, 0.12); }
  ping() {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = 'sine';
    o.frequency.value = 1240;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(0.035, t0 + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + 1.2);
    o.connect(g).connect(this.master);
    o.start(t0);
    o.stop(t0 + 1.3);
    this.tone(1860, 0.9, 'sine', 0.012, 0, 0.04);
  }
  blackbox() {
    this.tone(220, 0.5, 'triangle', 0.1, 40);
    this.tone(330, 0.6, 'sine', 0.08, 0, 0.12);
    this.tone(440, 0.7, 'sine', 0.07, 0, 0.24);
    this.noiseBurst(0.6, 400, 0.1);
  }
  success() {
    [392, 523, 659, 784].forEach((f, i) => this.tone(f, 0.55, 'sine', 0.07, 0, i * 0.13));
    this.noiseBurst(0.7, 700, 0.06);
  }
  fail() {
    [220, 196, 147].forEach((f, i) => this.tone(f, 0.7, 'triangle', 0.09, -20, i * 0.16));
    this.noiseBurst(0.9, 200, 0.08);
  }
  surface() {
    this.noiseBurst(0.7, 900, 0.14);
    this.tone(300, 0.3, 'sine', 0.07, 300);
  }
  boost() {
    this.noiseBurst(0.18, 600, 0.04);
  }
  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.05);
  }
}

// ============================================================
// DECOMP — canvas renderer
// ============================================================

import { WORLD } from './world.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const TAU = Math.PI * 2;

function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rgb(c) { return `rgb(${c[0]},${c[1]},${c[2]})`; }
function rgba(c, a) { return `rgba(${c[0]},${c[1]},${c[2]},${a})`; }

const PALETTE = [
  [0, [30, 132, 161]],
  [25, [16, 99, 132]],
  [60, [8, 67, 95]],
  [110, [4, 43, 67]],
  [170, [3, 24, 42]],
  [230, [2, 14, 27]],
  [300, [0, 6, 13]],
];

function waterColor(depth) {
  const d = clamp(depth, 0, 300);
  for (let i = 0; i < PALETTE.length - 1; i++) {
    const [d0, c0] = PALETTE[i];
    const [d1, c1] = PALETTE[i + 1];
    if (d >= d0 && d <= d1) {
      const t = (d - d0) / (d1 - d0);
      return [lerp(c0[0], c1[0], t), lerp(c0[1], c1[1], t), lerp(c0[2], c1[2], t)];
    }
  }
  return PALETTE[PALETTE.length - 1][1];
}

const TIER = [
  ['#ffd88a', '255,200,110'],
  ['#ffb454', '255,166,78'],
  ['#ff8a4d', '255,122,65'],
  ['#ff6347', '255,84,58'],
];

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.W = 1; this.H = 1; this.dpr = 1;
    this.scale = 12;
    this.camX = 60; this.camY = 30;
    this.time = 0;
    this.light = document.createElement('canvas');
    this.lctx = this.light.getContext('2d');
    this.diverAngle = 0;
    this.ripples = [];
    this.resize = this.resize.bind(this);
    window.addEventListener('resize', this.resize);
    this.resize();
    this._buildDecor();
  }

  resize() {
    const r = this.canvas.getBoundingClientRect();
    this.W = Math.max(1, r.width);
    this.H = Math.max(1, r.height);
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(this.W * this.dpr);
    this.canvas.height = Math.round(this.H * this.dpr);
    this.light.width = Math.round(this.W * this.dpr);
    this.light.height = Math.round(this.H * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.scale = this.H / WORLD.viewM;
  }

  _buildDecor() {
    const rnd = mulberry32(7781);
    this.kelp = [];
    for (let i = 0; i < 26; i++) {
      this.kelp.push({
        x: rnd() < 0.5 ? 6 + rnd() * 16 : 100 + rnd() * 15,
        depth: 62 + rnd() * 62,
        height: 7 + rnd() * 18,
        phase: rnd() * TAU,
        width: 1.4 + rnd() * 2.6,
        hue: 120 + rnd() * 50,
      });
    }
    this.rocks = [];
    for (let i = 0; i < 18; i++) {
      this.rocks.push({
        x: rnd() < 0.5 ? rnd() * 20 : 100 + rnd() * 20,
        depth: 100 + rnd() * 170,
        r: 2 + rnd() * 7,
        phase: rnd() * TAU,
      });
    }
    this.stars = [];
    for (let i = 0; i < 40; i++) {
      this.stars.push({ x: rnd(), y: rnd() * 0.5, a: 0.1 + rnd() * 0.5 });
    }
    this.rayPhase = rnd() * 10;
    this.snowSeed = rnd() * 1000;
    this.currentSeed = rnd() * 1000;
  }

  mapX(x) { return (x - this.camX) * this.scale + this.W / 2; }
  mapY(d) { return (d - this.camY) * this.scale + this.H / 2; }

  _setCam(cam) {
    const visW = this.W / this.scale;
    this.camX = visW >= WORLD.width ? WORLD.width / 2 : clamp(cam.x, visW / 2, WORLD.width - visW / 2);
    this.camY = cam.y;
    this.visW = visW;
  }

  // ============================================================
  // BACKGROUND
  // ============================================================
  drawBackdrop(camY, t, opts = {}) {
    const { W, H, ctx } = this;
    const topDepth = camY - WORLD.viewM / 2;
    const botDepth = camY + WORLD.viewM / 2;
    const cTop = waterColor(topDepth);
    const cBot = waterColor(botDepth);
    const g = ctx.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, rgb(cTop));
    g.addColorStop(0.55, rgb(waterColor(camY)));
    g.addColorStop(1, rgb(cBot));
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);

    // deep haze / depth vignette
    const vg = ctx.createRadialGradient(W * 0.5, H * 0.45, H * 0.1, W * 0.5, H * 0.55, H * 0.95);
    vg.addColorStop(0, 'rgba(0,10,18,0)');
    vg.addColorStop(0.62, 'rgba(0,5,11,0.16)');
    vg.addColorStop(1, 'rgba(0,2,6,0.62)');
    ctx.fillStyle = vg;
    ctx.fillRect(0, 0, W, H);

    // subtle vertical bands of light in the upper water
    if (camY < 120) {
      const fade = clamp(1 - camY / 130, 0, 1);
      const bg = ctx.createLinearGradient(W * 0.35, 0, W * 0.62, H);
      bg.addColorStop(0, `rgba(80,210,235,${0.11 * fade})`);
      bg.addColorStop(0.5, `rgba(40,160,195,${0.04 * fade})`);
      bg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, W, H);
    }
  }

  drawSky(t) {
    const { ctx, W } = this;
    const waterY = this.mapY(0);
    if (waterY <= -20) return;
    const top = Math.max(-H_UNUSED, waterY - this.H * 0.8);
    const g = ctx.createLinearGradient(0, Math.max(0, top), 0, waterY);
    g.addColorStop(0, '#081827');
    g.addColorStop(0.45, '#173e52');
    g.addColorStop(0.78, '#3d7481');
    g.addColorStop(1, '#d69b70');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, Math.max(0, waterY));

    // stars
    ctx.save();
    for (const s of this.stars) {
      ctx.fillStyle = `rgba(210,240,255,${s.a * 0.7})`;
      ctx.fillRect(s.x * W, s.y * Math.max(0, waterY - 20), 1.2, 1.2);
    }
    ctx.restore();

    // horizon glow
    const hg = ctx.createRadialGradient(W * 0.72, waterY, 4, W * 0.72, waterY, W * 0.45);
    hg.addColorStop(0, 'rgba(255,205,150,0.4)');
    hg.addColorStop(0.4, 'rgba(255,160,110,0.12)');
    hg.addColorStop(1, 'rgba(255,140,100,0)');
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = hg;
    ctx.fillRect(0, 0, W, Math.max(0, waterY));
    ctx.restore();

    // distant clouds
    ctx.save();
    ctx.globalAlpha = 0.16;
    ctx.fillStyle = '#d8eef5';
    for (let i = 0; i < 4; i++) {
      const cx = ((i * 0.31 + t * 0.003) % 1.3 - 0.15) * W;
      const cy = waterY - 40 - (i % 3) * 22;
      const cw = 90 + i * 34;
      ctx.beginPath();
      ctx.ellipse(cx, cy, cw, 6, 0, 0, TAU);
      ctx.ellipse(cx + cw * 0.4, cy - 5, cw * 0.55, 4, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // waterline
    const wl = ctx.createLinearGradient(0, waterY - 2, 0, waterY + 10);
    wl.addColorStop(0, 'rgba(150,230,245,0.65)');
    wl.addColorStop(1, 'rgba(60,150,175,0)');
    ctx.fillStyle = wl;
    ctx.fillRect(0, waterY - 2, W, 14);

    // waves
    ctx.save();
    ctx.strokeStyle = 'rgba(178,238,250,0.34)';
    ctx.lineWidth = 1;
    for (let r = 0; r < 3; r++) {
      ctx.beginPath();
      for (let x = -10; x <= W + 10; x += 8) {
        const y = waterY + r * 4 + Math.sin(x * 0.024 + t * 0.9 + r * 1.6) * (1.8 - r * 0.4);
        if (x === -10) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.globalAlpha = 0.5 - r * 0.13;
      ctx.stroke();
    }
    ctx.restore();

    this.drawBoat(W * 0.72, waterY, t);
  }

  drawBoat(x, waterY, t) {
    const { ctx } = this;
    const bob = Math.sin(t * 0.85) * 2.2;
    const y = waterY + bob;
    ctx.save();
    ctx.translate(x, y);

    // reflection
    ctx.save();
    ctx.globalAlpha = 0.16;
    ctx.fillStyle = '#ffce9e';
    ctx.beginPath();
    ctx.ellipse(0, 14, 64, 4, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    // hull
    ctx.fillStyle = '#101f27';
    ctx.beginPath();
    ctx.moveTo(-62, -8);
    ctx.lineTo(66, -8);
    ctx.lineTo(48, 8);
    ctx.lineTo(-46, 8);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(255,190,130,0.25)';
    ctx.fillRect(-48, -8, 98, 2.5);

    // cabin
    ctx.fillStyle = '#132832';
    ctx.beginPath();
    ctx.moveTo(-24, -8);
    ctx.lineTo(-18, -31);
    ctx.lineTo(16, -31);
    ctx.lineTo(25, -8);
    ctx.closePath();
    ctx.fill();
    // windows
    ctx.fillStyle = 'rgba(255,206,150,0.7)';
    ctx.fillRect(-13, -26, 6, 5);
    ctx.fillRect(0, -26, 6, 5);
    ctx.fillStyle = 'rgba(120,220,245,0.3)';
    ctx.fillRect(10, -26, 5, 5);

    // mast + crane
    ctx.strokeStyle = '#0d1c24';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(34, -8); ctx.lineTo(34, -50);
    ctx.moveTo(34, -50); ctx.lineTo(52, -36);
    ctx.stroke();
    // hanging cable
    ctx.strokeStyle = 'rgba(200,230,235,0.2)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(52, -36);
    ctx.lineTo(52, -20 + Math.sin(t * 1.2) * 2);
    ctx.stroke();

    // beacon
    const blink = (Math.sin(t * 2.4) + 1) / 2;
    ctx.fillStyle = `rgba(255,120,90,${0.35 + blink * 0.65})`;
    ctx.beginPath();
    ctx.arc(34, -51, 2, 0, TAU);
    ctx.fill();
    const glow = ctx.createRadialGradient(34, -51, 0, 34, -51, 18);
    glow.addColorStop(0, `rgba(255,100,80,${0.22 + blink * 0.2})`);
    glow.addColorStop(1, 'rgba(255,100,80,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(16, -69, 36, 36);

    ctx.restore();
  }

  drawRays(camY, t) {
    if (camY > 150) return;
    const { ctx, W, H } = this;
    const waterY = this.mapY(0);
    const fade = clamp(1 - camY / 150, 0, 1);
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    ctx.translate(W * 0.72, waterY);
    const rays = [
      [-0.55, 0.28, 0.1, 0.8],
      [-0.32, 0.42, 0.13, 1.0],
      [-0.05, 0.24, 0.07, 0.6],
      [0.18, 0.36, 0.1, 0.7],
      [0.43, 0.18, 0.06, 0.5],
    ];
    for (let i = 0; i < rays.length; i++) {
      const [ang, w, a, len] = rays[i];
      const sway = Math.sin(t * 0.16 + i * 1.7) * 0.035;
      const L = H * len * 1.4;
      const dx = Math.sin(ang + sway) * L;
      const dy = Math.cos(ang + sway) * L;
      const wx = Math.cos(ang) * W * w;
      const grad = ctx.createLinearGradient(0, 0, dx, dy);
      grad.addColorStop(0, `rgba(180,245,255,${a * fade * 0.42})`);
      grad.addColorStop(0.5, `rgba(130,225,245,${a * fade * 0.14})`);
      grad.addColorStop(1, 'rgba(80,190,220,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(-wx * 0.2, 0);
      ctx.lineTo(wx * 0.2, 0);
      ctx.lineTo(dx + wx, dy);
      ctx.lineTo(dx - wx, dy);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  drawCliffs(camY) {
    const { ctx, H, W } = this;
    const top = this.mapY(90);
    if (top > H) return;
    const startY = Math.max(0, top);
    const rnd = mulberry32(441);
    const step = 26;
    ctx.save();

    // left wall
    ctx.beginPath();
    ctx.moveTo(0, H);
    ctx.lineTo(0, startY - 20);
    let x = 0;
    for (let y = startY - 20; y <= H + 30; y += step) {
      const d = (y - H / 2) / this.scale + camY;
      const w = 26 + Math.sin(d * 0.11 + 1.7) * 12 + Math.sin(d * 0.31) * 6;
      ctx.lineTo(w, y + 4);
      x = w;
    }
    ctx.lineTo(0, H + 30);
    ctx.closePath();
    const lg = ctx.createLinearGradient(0, 0, 90, 0);
    lg.addColorStop(0, 'rgba(1,7,12,0.96)');
    lg.addColorStop(0.7, 'rgba(2,12,19,0.7)');
    lg.addColorStop(1, 'rgba(2,12,19,0)');
    ctx.fillStyle = lg;
    ctx.fill();

    // right wall
    ctx.beginPath();
    ctx.moveTo(W, H + 30);
    ctx.lineTo(W, startY + 30);
    for (let y = startY + 30; y <= H + 40; y += step) {
      const d = (y - H / 2) / this.scale + camY;
      const w = W - (30 + Math.sin(d * 0.09 + 4.2) * 16 + Math.sin(d * 0.27) * 7);
      ctx.lineTo(w, y + 6);
    }
    ctx.lineTo(W, H + 40);
    ctx.closePath();
    const rg = ctx.createLinearGradient(W, 0, W - 100, 0);
    rg.addColorStop(0, 'rgba(1,6,11,0.97)');
    rg.addColorStop(0.72, 'rgba(2,10,17,0.65)');
    rg.addColorStop(1, 'rgba(2,10,17,0)');
    ctx.fillStyle = rg;
    ctx.fill();

    // rim highlights
    ctx.strokeStyle = 'rgba(70,150,175,0.08)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    for (let y = startY; y <= H; y += step) {
      const d = (y - H / 2) / this.scale + camY;
      const w = 26 + Math.sin(d * 0.11 + 1.7) * 12 + Math.sin(d * 0.31) * 6;
      if (y === startY) ctx.moveTo(w, y + 4); else ctx.lineTo(w, y + 4);
    }
    ctx.stroke();
    ctx.restore();
  }

  drawKelp(camY, t) {
    const { ctx } = this;
    for (const k of this.kelp) {
      if (k.depth - k.height > camY + 45 || k.depth < camY - 55) continue;
      const bx = this.mapX(k.x);
      const by = this.mapY(k.depth);
      ctx.save();
      ctx.globalAlpha = 0.55;
      ctx.strokeStyle = `hsla(${k.hue}, 42%, 26%, 0.9)`;
      ctx.lineWidth = k.width * 0.42;
      ctx.beginPath();
      ctx.moveTo(bx, by);
      const sway = Math.sin(t * 0.55 + k.phase) * 4;
      const midX = bx + sway * 0.5;
      const midY = by - k.height * 0.5 * this.scale * 0.5;
      const tipX = bx + sway;
      const tipY = by - k.height * this.scale * 0.5;
      ctx.quadraticCurveTo(midX, midY, tipX, tipY);
      ctx.stroke();
      // blades
      for (let i = 1; i <= 4; i++) {
        const p = i / 5;
        const px = lerp(lerp(bx, midX, p * 2), tipX, Math.max(0, p * 2 - 1));
        const py = lerp(lerp(by, midY, p * 2), tipY, Math.max(0, p * 2 - 1));
        const dir = i % 2 ? 1 : -1;
        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.quadraticCurveTo(px + dir * 8, py - 4, px + dir * 11, py - 9);
        ctx.strokeStyle = `hsla(${k.hue}, 45%, 30%, 0.55)`;
        ctx.lineWidth = k.width * 0.34;
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  drawSeabed(camY, t) {
    const { ctx, W, H } = this;
    const floorY = this.mapY(WORLD.floor);
    if (floorY < -60) return;
    const rnd = mulberry32(991);
    const g = ctx.createLinearGradient(0, floorY - 40, 0, H);
    g.addColorStop(0, 'rgba(1,10,15,0.4)');
    g.addColorStop(0.35, 'rgba(2,12,17,0.95)');
    g.addColorStop(1, 'rgba(0,3,7,1)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(0, H);
    let yy = floorY;
    ctx.lineTo(0, floorY + 8);
    for (let x = 0; x <= W + 20; x += 34) {
      const n = Math.sin(x * 0.013 + 1.2) * 9 + Math.sin(x * 0.037) * 5;
      ctx.lineTo(x, floorY + 6 + n);
    }
    ctx.lineTo(W, H);
    ctx.closePath();
    ctx.fill();

    // rocks
    for (let i = 0; i < 12; i++) {
      const rx = rnd() * W;
      const rw = 12 + rnd() * 42;
      const rh = 5 + rnd() * 16;
      const ry = floorY + 10 + rnd() * 26;
      ctx.fillStyle = 'rgba(1,7,12,0.9)';
      ctx.beginPath();
      ctx.ellipse(rx, ry, rw, rh, 0, Math.PI, 0);
      ctx.fill();
    }
    ctx.restore();
  }

  drawWreck(camY, t, special) {
    const { ctx } = this;
    const y = this.mapY(288);
    if (y < -140 || y > this.H + 160) return;
    const x = this.mapX(58);
    const s = this.scale;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(-0.1);

    // shadowy hull
    ctx.fillStyle = 'rgba(2,8,12,0.92)';
    ctx.beginPath();
    ctx.moveTo(-22 * s * 0.16, 2 * s * 0.16);
    ctx.lineTo(20 * s * 0.16, 0);
    ctx.lineTo(26 * s * 0.16, 4 * s * 0.16);
    ctx.lineTo(18 * s * 0.16, 8 * s * 0.16);
    ctx.lineTo(-16 * s * 0.16, 10 * s * 0.16);
    ctx.closePath();
    ctx.fill();
    // broken ribs
    ctx.strokeStyle = 'rgba(60,120,135,0.16)';
    ctx.lineWidth = 1.1;
    for (let i = 0; i < 6; i++) {
      const rx = (-18 + i * 6) * s * 0.16;
      ctx.beginPath();
      ctx.moveTo(rx, 1 * s * 0.16);
      ctx.lineTo(rx + 1.6, -5 * s * 0.16);
      ctx.stroke();
    }
    // portholes
    for (let i = 0; i < 3; i++) {
      ctx.fillStyle = 'rgba(70,190,200,0.1)';
      ctx.beginPath();
      ctx.arc((-10 + i * 8) * s * 0.16, 4.2 * s * 0.16, 0.7, 0, TAU);
      ctx.fill();
    }
    // debris
    ctx.fillStyle = 'rgba(2,8,12,0.8)';
    ctx.fillRect(-27 * s * 0.16, 8 * s * 0.16, 9 * s * 0.16, 2 * s * 0.16);
    ctx.restore();

    if (special) {
      // beacon beam upward
      const bx = this.mapX(58);
      const by = this.mapY(288);
      const beam = ctx.createLinearGradient(0, by - 260, 0, by);
      beam.addColorStop(0, 'rgba(255,150,80,0)');
      beam.addColorStop(0.7, 'rgba(255,140,70,0.035)');
      beam.addColorStop(1, 'rgba(255,140,70,0.14)');
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.fillStyle = beam;
      ctx.fillRect(bx - 9, by - 260, 18, 260);
      ctx.restore();
    }
  }

  drawVents(run, t) {
    const { ctx } = this;
    for (const v of run.vents) {
      const x = this.mapX(v.x);
      const y = this.mapY(v.depth);
      if (y < -60 || y > this.H + 40) continue;
      const ph = (t * v.rate + v.phase) % 1;
      for (let i = 0; i < 3; i++) {
        const p = (ph + i / 3) % 1;
        const yy = y - p * 26;
        const xx = x + Math.sin(p * 6 + v.phase) * 5;
        ctx.fillStyle = `rgba(120,210,220,${0.05 * (1 - p)})`;
        ctx.beginPath();
        ctx.arc(xx, yy, 3 + p * 5, 0, TAU);
        ctx.fill();
      }
    }
  }

  // ============================================================
  // ENTITIES
  // ============================================================
  drawLoot(it, t) {
    if (it.taken) return;
    const { ctx } = this;
    const x = this.mapX(it.x);
    const y = this.mapY(it.depth + Math.sin(t * 1.3 + it.bob) * 0.22);
    const s = this.scale * 0.32;
    const tier = TIER[Math.min(3, it.tier)];
    const pulse = 0.6 + Math.sin(t * 2 + it.phase) * 0.4;

    if (it.kind === 'blackbox') {
      this.drawBlackBox(x, y, s, t);
      return;
    }

    // glow
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const glow = ctx.createRadialGradient(x, y, 0, x, y, s * 6);
    glow.addColorStop(0, `rgba(${tier[1]},${0.16 + pulse * 0.13})`);
    glow.addColorStop(0.5, `rgba(${tier[1]},0.05)`);
    glow.addColorStop(1, `rgba(${tier[1]},0)`);
    ctx.fillStyle = glow;
    ctx.fillRect(x - s * 6, y - s * 6, s * 12, s * 12);
    ctx.restore();

    ctx.save();
    ctx.translate(x, y);
    const bob = Math.sin(t * 1.3 + it.phase) * 0.5;
    ctx.rotate(Math.sin(it.phase + t * 0.5) * 0.08);
    ctx.translate(0, bob);

    if (it.kind === 'crate') {
      ctx.fillStyle = '#4b3520';
      ctx.fillRect(-s * 0.85, -s * 0.62, s * 1.7, s * 1.24);
      ctx.fillStyle = `rgba(${tier[1]},0.32)`;
      ctx.fillRect(-s * 0.85, -s * 0.62, s * 1.7, s * 0.16);
      ctx.fillRect(-s * 0.85, s * 0.34, s * 1.7, s * 0.16);
      ctx.strokeStyle = `rgba(${tier[1]},0.55)`;
      ctx.lineWidth = 1;
      ctx.strokeRect(-s * 0.85, -s * 0.62, s * 1.7, s * 1.24);
      ctx.beginPath();
      ctx.moveTo(-s * 0.8, 0); ctx.lineTo(s * 0.8, 0);
      ctx.moveTo(0, -s * 0.6); ctx.lineTo(0, s * 0.6);
      ctx.strokeStyle = `rgba(${tier[1]},0.22)`;
      ctx.stroke();
      // emblem
      ctx.fillStyle = `rgba(${tier[1]},${0.5 + pulse * 0.4})`;
      ctx.fillRect(-s * 0.13, -s * 0.13, s * 0.26, s * 0.26);
    } else if (it.kind === 'urn') {
      ctx.fillStyle = '#2a3a3c';
      ctx.beginPath();
      ctx.moveTo(-s * 0.5, -s * 0.6);
      ctx.bezierCurveTo(-s * 0.9, -s * 0.1, -s * 0.65, s * 0.7, 0, s * 0.72);
      ctx.bezierCurveTo(s * 0.65, s * 0.7, s * 0.9, -s * 0.1, s * 0.5, -s * 0.6);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = `rgba(${tier[1]},0.45)`;
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = `rgba(${tier[1]},0.4)`;
      ctx.fillRect(-s * 0.28, -s * 0.8, s * 0.56, s * 0.22);
      ctx.beginPath();
      ctx.arc(0, 0.1, s * 0.22, 0, TAU);
      ctx.stroke();
    } else {
      // barrel
      ctx.fillStyle = '#253b3c';
      ctx.beginPath();
      ctx.roundRect(-s * 0.55, -s * 0.8, s * 1.1, s * 1.6, s * 0.2);
      ctx.fill();
      ctx.strokeStyle = `rgba(${tier[1]},0.4)`;
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = `rgba(${tier[1]},0.28)`;
      ctx.fillRect(-s * 0.58, -s * 0.25, s * 1.16, s * 0.16);
      ctx.fillRect(-s * 0.58, s * 0.18, s * 1.16, s * 0.16);
      ctx.fillStyle = `rgba(${tier[1]},0.6)`;
      ctx.beginPath();
      ctx.arc(0, -s * 0.1, s * 0.09, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawBlackBox(x, y, s, t) {
    const { ctx } = this;
    const pulse = (Math.sin(t * 3) + 1) / 2;
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const glow = ctx.createRadialGradient(x, y, 0, x, y, s * 8);
    glow.addColorStop(0, `rgba(255,130,70,${0.2 + pulse * 0.18})`);
    glow.addColorStop(1, 'rgba(255,130,70,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(x - s * 8, y - s * 8, s * 16, s * 16);
    ctx.restore();

    ctx.save();
    ctx.translate(x, y);
    const bob = Math.sin(t * 1.1) * 0.8;
    ctx.translate(0, bob);
    ctx.fillStyle = '#241a12';
    ctx.fillRect(-s * 1.15, -s * 0.62, s * 2.3, s * 1.24);
    ctx.strokeStyle = 'rgba(255,170,90,0.75)';
    ctx.lineWidth = 1.2;
    ctx.strokeRect(-s * 1.15, -s * 0.62, s * 2.3, s * 1.24);
    ctx.fillStyle = 'rgba(255,180,90,0.16)';
    ctx.fillRect(-s * 0.98, -s * 0.45, s * 1.96, s * 0.9);
    // signal light
    ctx.fillStyle = pulse > 0.5 ? '#ffb15c' : '#7a3a18';
    ctx.beginPath();
    ctx.arc(s * 0.78, -s * 0.3, s * 0.12, 0, TAU);
    ctx.fill();
    // stripes
    ctx.fillStyle = 'rgba(255,160,80,0.45)';
    for (let i = 0; i < 3; i++) ctx.fillRect(-s * 0.8, -s * 0.2 + i * s * 0.22, s * 1.6, s * 0.06);
    ctx.restore();

    // floating label
    ctx.save();
    ctx.font = `600 ${Math.max(8, s * 0.62)}px ui-monospace, monospace`;
    ctx.fillStyle = `rgba(255,190,130,${0.5 + pulse * 0.4})`;
    ctx.textAlign = 'center';
    ctx.fillText('BLACK BOX', x, y - s * 2.2);
    ctx.restore();
  }

  drawCanister(c, t) {
    if (c.taken) return;
    const { ctx } = this;
    const x = this.mapX(c.x);
    const y = this.mapY(c.depth + Math.sin(t * 1.6 + c.phase) * 0.25);
    const s = this.scale * 0.3;
    const pulse = 0.55 + Math.sin(t * 2.6 + c.phase) * 0.45;

    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const glow = ctx.createRadialGradient(x, y, 0, x, y, s * 6.5);
    glow.addColorStop(0, `rgba(80,255,220,${0.11 + pulse * 0.12})`);
    glow.addColorStop(1, 'rgba(80,255,220,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(x - s * 7, y - s * 7, s * 14, s * 14);
    ctx.restore();

    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = '#0d4a4a';
    ctx.beginPath();
    ctx.roundRect(-s * 0.48, -s * 0.85, s * 0.96, s * 1.7, s * 0.3);
    ctx.fill();
    ctx.strokeStyle = `rgba(90,255,225,${0.4 + pulse * 0.4})`;
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = 'rgba(140,255,235,0.75)';
    ctx.fillRect(-s * 0.18, -s * 0.85, s * 0.36, s * 0.28);
    ctx.fillStyle = '#8ffff0';
    ctx.fillRect(-s * 0.06, -s * 0.5, s * 0.12, s * 0.6);
    ctx.fillRect(-s * 0.24, -s * 0.26, s * 0.48, s * 0.12);
    ctx.restore();
  }

  drawJelly(j, t) {
    const { ctx } = this;
    const d = j.renderDepth ?? j.depth;
    const x = this.mapX(j.x);
    const y = this.mapY(d);
    const s = this.scale * 0.55 * j.size;
    if (y < -80 || y > this.H + 80) return;

    ctx.save();
    ctx.translate(x, y);
    const pulse = 1 + Math.sin(t * 1.6 + j.phase) * 0.09;
    ctx.scale(pulse, 2 - pulse);

    // glow
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, s * 3.2);
    glow.addColorStop(0, 'rgba(255,120,190,0.14)');
    glow.addColorStop(0.5, 'rgba(180,90,255,0.05)');
    glow.addColorStop(1, 'rgba(180,90,255,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(-s * 3.4, -s * 3.4, s * 6.8, s * 6.8);
    ctx.restore();

    // tentacles
    ctx.strokeStyle = 'rgba(255,150,205,0.3)';
    ctx.lineWidth = Math.max(0.7, s * 0.05);
    for (let i = 0; i < 6; i++) {
      const ox = (i - 2.5) * s * 0.16;
      ctx.beginPath();
      ctx.moveTo(ox, s * 0.2);
      ctx.bezierCurveTo(
        ox + Math.sin(t * 1.1 + i) * s * 0.25, s * 0.9,
        ox + Math.sin(t * 0.9 + i * 2) * s * 0.3, s * 1.4,
        ox + Math.sin(t * 1.3 + i) * s * 0.15, s * 2
      );
      ctx.stroke();
    }

    // bell
    const bell = ctx.createLinearGradient(0, -s * 0.6, 0, s * 0.35);
    bell.addColorStop(0, 'rgba(255,190,230,0.42)');
    bell.addColorStop(0.5, 'rgba(225,120,220,0.24)');
    bell.addColorStop(1, 'rgba(140,80,220,0.06)');
    ctx.fillStyle = bell;
    ctx.beginPath();
    ctx.moveTo(-s * 0.6, s * 0.1);
    ctx.bezierCurveTo(-s * 0.72, -s * 0.7, s * 0.72, -s * 0.7, s * 0.6, s * 0.1);
    ctx.bezierCurveTo(s * 0.4, s * 0.34, -s * 0.4, s * 0.34, -s * 0.6, s * 0.1);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,190,235,0.5)';
    ctx.lineWidth = Math.max(0.6, s * 0.035);
    ctx.stroke();
    // rim glow
    ctx.strokeStyle = 'rgba(255,220,250,0.7)';
    ctx.beginPath();
    ctx.moveTo(-s * 0.58, s * 0.11);
    ctx.quadraticCurveTo(0, s * 0.3, s * 0.58, s * 0.11);
    ctx.stroke();
    ctx.restore();
  }

  drawFish(f, t) {
    const { ctx } = this;
    const x = this.mapX(f.x);
    const y = this.mapY(f.depth + Math.sin(t * f.wobble + f.phase) * 1.2);
    const s = this.scale * 0.13 * f.size;
    if (x < -30 || x > this.W + 30 || y < -20 || y > this.H + 20) return;
    const dir = f.speed >= 0 ? 1 : -1;
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(dir, 1);
    if (f.deep) {
      ctx.fillStyle = 'rgba(70,140,170,0.24)';
      ctx.beginPath();
      ctx.ellipse(0, 0, s * 2.1, s * 0.7, 0.12, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(120,255,230,0.5)';
      ctx.beginPath();
      ctx.arc(s * 1.4, -s * 0.1, Math.max(0.7, s * 0.13), 0, TAU);
      ctx.fill();
    } else {
      ctx.fillStyle = 'rgba(6,26,36,0.6)';
      ctx.beginPath();
      ctx.ellipse(0, 0, s * 2.2, s * 0.72, 0.1, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-s * 1.8, 0);
      ctx.lineTo(-s * 3, -s * 0.8);
      ctx.lineTo(-s * 2.7, s * 0.7);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  drawDiver(run, t, xDepth, opts = {}) {
    const { ctx } = this;
    const x = this.mapX(xDepth.x);
    const y = this.mapY(xDepth.depth);
    const s = this.scale * 0.1;
    const vx = opts.vx ?? 0;
    const vy = opts.vy ?? 0;
    const speed = Math.hypot(vx, vy);
    let target = Math.atan2(vy, vx || 0.001);
    if (speed < 0.5) target = opts.idleAngle ?? -0.08;
    // smooth
    let diff = target - this.diverAngle;
    while (diff > Math.PI) diff -= TAU;
    while (diff < -Math.PI) diff += TAU;
    this.diverAngle += diff * 0.18;
    const angle = clamp(this.diverAngle, -1.25, 1.25);
    const facing = vx < -0.2 ? -1 : 1;

    // green glow around diver
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const glow = ctx.createRadialGradient(x, y, 0, x, y, s * 26);
    glow.addColorStop(0, 'rgba(120,235,255,0.16)');
    glow.addColorStop(0.4, 'rgba(70,190,220,0.05)');
    glow.addColorStop(1, 'rgba(70,190,220,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(x - s * 27, y - s * 27, s * 54, s * 54);
    ctx.restore();

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.scale(facing, 1);
    if (run?.invuln > 0 && Math.floor(t * 12) % 2 === 0) ctx.globalAlpha = 0.5;

    const kick = Math.sin(t * (speed > 2 ? 14 : 7)) * (0.35 + Math.min(0.65, speed / 6));

    // trailing fins / legs
    ctx.strokeStyle = '#08141c';
    ctx.lineWidth = s * 2.2;
    ctx.lineCap = 'round';
    for (let leg = 0; leg < 2; leg++) {
      const side = leg === 0 ? -1 : 1;
      const k = kick * side;
      ctx.beginPath();
      ctx.moveTo(-s * 5, side * s * 1.2);
      ctx.quadraticCurveTo(-s * 10, side * s * 2.4 + k * s * 3, -s * 14, side * s * 2.4 + k * s * 5.5);
      ctx.strokeStyle = leg === 0 ? '#0a1a24' : '#0d202b';
      ctx.lineWidth = s * 2;
      ctx.stroke();
      // fin
      ctx.save();
      ctx.translate(-s * 14, side * s * 2.4 + k * s * 5.5);
      ctx.rotate(k * 0.5 - 0.15);
      ctx.fillStyle = leg === 0 ? '#c98f3a' : '#e0a445';
      ctx.beginPath();
      ctx.ellipse(-s * 2.8, 0, s * 3.6, s * 0.85, 0.16, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(255,225,150,0.4)';
      ctx.beginPath();
      ctx.ellipse(-s * 3.2, -s * 0.18, s * 2.4, s * 0.32, 0.16, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // tank
    ctx.save();
    ctx.translate(-s * 2.2, -s * 4.4);
    ctx.rotate(-0.1);
    ctx.fillStyle = '#16262c';
    ctx.beginPath();
    ctx.roundRect(-s * 3.4, -s * 1.7, s * 7.4, s * 3.4, s * 1.2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(150,220,230,0.22)';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = 'rgba(190,245,255,0.35)';
    ctx.fillRect(-s * 2.6, -s * 1.2, s * 1.4, s * 2.4);
    ctx.fillStyle = '#c98f3a';
    ctx.fillRect(s * 3.2, -s * 0.55, s * 0.8, s * 1.1);
    ctx.restore();

    // body
    const body = ctx.createLinearGradient(-s * 6, -s * 4, s * 8, s * 5);
    body.addColorStop(0, '#0a151d');
    body.addColorStop(0.55, '#10222c');
    body.addColorStop(1, '#1b3a46');
    ctx.fillStyle = body;
    ctx.beginPath();
    ctx.ellipse(s * 1.5, 0, s * 8.2, s * 3.1, 0.02, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(120,225,245,0.25)';
    ctx.lineWidth = 1;
    ctx.stroke();

    // shoulder + arm
    ctx.strokeStyle = '#0d1f29';
    ctx.lineWidth = s * 1.9;
    ctx.beginPath();
    ctx.moveTo(s * 5.8, s * 1.2);
    ctx.quadraticCurveTo(s * 7, s * 4, s * 4.6, s * 5.6);
    ctx.stroke();
    // glove
    ctx.fillStyle = '#1d3a45';
    ctx.beginPath();
    ctx.arc(s * 4.4, s * 5.7, s * 1.1, 0, TAU);
    ctx.fill();

    // oxygen hose
    ctx.strokeStyle = 'rgba(120,200,210,0.35)';
    ctx.lineWidth = s * 0.55;
    ctx.beginPath();
    ctx.moveTo(-s * 4.5, -s * 3.2);
    ctx.quadraticCurveTo(-s * 6.5, -s * 1, -s * 3.5, s * 0.5);
    ctx.stroke();

    // head + helmet
    ctx.fillStyle = '#0d202a';
    ctx.beginPath();
    ctx.arc(s * 9.2, -s * 0.4, s * 3.15, 0, TAU);
    ctx.fill();
    // helmet shell
    ctx.fillStyle = '#17313b';
    ctx.beginPath();
    ctx.arc(s * 9.2, -s * 0.4, s * 3.4, 0, TAU);
    ctx.fill();
    // visor
    const visor = ctx.createLinearGradient(s * 7.5, -s * 3, s * 12, s * 2);
    visor.addColorStop(0, 'rgba(130,245,255,0.85)');
    visor.addColorStop(0.6, 'rgba(70,190,220,0.5)');
    visor.addColorStop(1, 'rgba(20,80,100,0.35)');
    ctx.fillStyle = visor;
    ctx.beginPath();
    ctx.ellipse(s * 10.3, -s * 0.3, s * 2.2, s * 2.6, 0.08, -1.9, 1.9);
    ctx.fill();
    // visor shine
    ctx.fillStyle = 'rgba(240,255,255,0.6)';
    ctx.beginPath();
    ctx.ellipse(s * 10, -s * 1.3, s * 1, s * 0.45, -0.4, 0, TAU);
    ctx.fill();

    // lamp housing
    ctx.fillStyle = '#c98f3a';
    ctx.fillRect(s * 12, -s * 1.4, s * 1.5, s * 2.8);
    ctx.fillStyle = '#fff8d8';
    ctx.beginPath();
    ctx.arc(s * 13.7, 0, s * 1.15, 0, TAU);
    ctx.fill();

    // tiny glints
    ctx.fillStyle = 'rgba(255,235,170,0.9)';
    ctx.beginPath();
    ctx.arc(s * 13.7, 0, s * 0.4, 0, TAU);
    ctx.fill();

    ctx.restore();

    // ---- headlamp beam ----
    if (!opts.noBeam) {
      const lamp = (run?.gear?.lamp || 15) * this.scale * 1.15;
      const dir = facing;
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      const bx = x + dir * s * 13;
      const by = y;
      const g = ctx.createRadialGradient(bx, by, 0, bx, by, lamp);
      g.addColorStop(0, 'rgba(180,248,255,0.19)');
      g.addColorStop(0.35, 'rgba(120,225,245,0.06)');
      g.addColorStop(1, 'rgba(70,180,210,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.arc(bx, by, lamp, -0.55 + (dir < 0 ? Math.PI : 0), 0.55 + (dir < 0 ? Math.PI : 0));
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    // bubbles from regulator
    if (!opts.noBubbles) {
      for (let i = 0; i < 3; i++) {
        const bp = ((t * 0.55 + i * 0.33) % 1);
        const bx = x - s * 1 + Math.sin(t * 3 + i) * 3;
        const by = y - s * 4 - bp * s * 22;
        ctx.strokeStyle = `rgba(180,245,255,${0.32 * (1 - bp)})`;
        ctx.lineWidth = 0.8;
        ctx.beginPath();
        ctx.arc(bx, by, 1 + bp * 2.4, 0, TAU);
        ctx.stroke();
      }
    }
  }

  // ============================================================
  // LIGHTING + FX
  // ============================================================
  drawLighting(run, xDepth, t) {
    const { W, H, ctx } = this;
    const depth = xDepth.depth;
    const darkness = 0.13 + clamp(depth / 290, 0, 1) * 0.78;
    const lc = this.lctx;
    lc.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    lc.clearRect(0, 0, W, H);
    lc.fillStyle = `rgba(0,3,8,${darkness})`;
    lc.fillRect(0, 0, W, H);
    lc.globalCompositeOperation = 'destination-out';

    const x = this.mapX(xDepth.x);
    const y = this.mapY(xDepth.depth);
    const s = this.scale * 0.1;
    const lamp = (run?.gear?.lamp || 15) * this.scale * 1.35;

    // soft bubble of visibility around the diver
    const amb = lamp * 0.42;
    const ag = lc.createRadialGradient(x, y, 0, x, y, amb);
    ag.addColorStop(0, 'rgba(0,0,0,0.92)');
    ag.addColorStop(0.55, 'rgba(0,0,0,0.62)');
    ag.addColorStop(1, 'rgba(0,0,0,0)');
    lc.fillStyle = ag;
    lc.beginPath();
    lc.arc(x, y, amb, 0, TAU);
    lc.fill();

    // directional headlamp cone (layered for soft edges)
    const facing = (run?.vx || 0) < -0.2 ? -1 : 1;
    const dirAng = facing > 0 ? 0.32 : Math.PI - 0.32;
    const bx = x + facing * s * 12;
    const by = y;
    for (let i = 0; i < 4; i++) {
      const spread = 0.62 - i * 0.1;
      const alpha = 0.2 + i * 0.2;
      lc.save();
      lc.beginPath();
      lc.moveTo(bx, by);
      lc.arc(bx, by, lamp * (0.75 + i * 0.07), dirAng - spread, dirAng + spread);
      lc.closePath();
      lc.clip();
      const g = lc.createRadialGradient(bx, by, 0, bx, by, lamp * (0.75 + i * 0.07));
      g.addColorStop(0, `rgba(0,0,0,${alpha})`);
      g.addColorStop(0.5, `rgba(0,0,0,${alpha * 0.75})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      lc.fillStyle = g;
      lc.fillRect(0, 0, W, H);
      lc.restore();
    }

    // surface light shaft
    if (this.camY < 90) {
      const waterY = this.mapY(0);
      const fade = clamp(1 - this.camY / 90, 0, 1);
      const wg = lc.createLinearGradient(0, waterY, 0, waterY + H * 0.75);
      wg.addColorStop(0, `rgba(0,0,0,${0.55 * fade})`);
      wg.addColorStop(1, 'rgba(0,0,0,0)');
      lc.fillStyle = wg;
      lc.fillRect(0, 0, W, H);
    }

    lc.globalCompositeOperation = 'source-over';
    lc.setTransform(1, 0, 0, 1, 0, 0);
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.drawImage(this.light, 0, 0);
    ctx.restore();

    // additive lamp bloom on top
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const bloom = ctx.createRadialGradient(bx, by, 0, bx, by, lamp * 0.65);
    bloom.addColorStop(0, 'rgba(160,240,255,0.10)');
    bloom.addColorStop(0.35, 'rgba(90,200,230,0.035)');
    bloom.addColorStop(1, 'rgba(60,160,200,0)');
    ctx.fillStyle = bloom;
    ctx.fillRect(bx - lamp, by - lamp, lamp * 2, lamp * 2);
    ctx.restore();
  }

  drawCeiling(run, t) {
    const { ctx, W } = this;
    const c = run.ceiling;
    if (c == null || c < 0.8) return;
    const y = this.mapY(c);
    if (y < -30 || y > this.H + 30) return;

    ctx.save();
    // danger tint above the ceiling
    g_tint: {
      const waterY = Math.max(0, this.mapY(0));
      if (y > waterY + 2) {
        const g = ctx.createLinearGradient(0, waterY, 0, y);
        g.addColorStop(0, 'rgba(255,60,50,0.015)');
        g.addColorStop(0.7, 'rgba(255,70,50,0.04)');
        g.addColorStop(1, 'rgba(255,90,60,0.09)');
        ctx.fillStyle = g;
        ctx.fillRect(0, waterY, W, y - waterY);
      }
    }

    // dashed line
    ctx.setLineDash([10, 9]);
    ctx.lineDashOffset = -t * 26;
    ctx.strokeStyle = 'rgba(255,180,84,0.8)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
    ctx.stroke();
    ctx.setLineDash([]);

    // glow
    ctx.globalCompositeOperation = 'screen';
    const g = ctx.createLinearGradient(0, y - 16, 0, y + 16);
    g.addColorStop(0, 'rgba(255,150,60,0)');
    g.addColorStop(0.5, 'rgba(255,170,80,0.1)');
    g.addColorStop(1, 'rgba(255,150,60,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, y - 16, W, 32);
    ctx.globalCompositeOperation = 'source-over';

    // label
    const label = `N₂ CEILING  ${Math.round(c)} M`;
    ctx.font = '600 9px ui-monospace, SFMono-Regular, Menlo, monospace';
    const tw = ctx.measureText(label).width;
    const lx = Math.min(W - tw - 44, 92);
    ctx.fillStyle = 'rgba(8,5,2,0.72)';
    ctx.fillRect(lx - 8, y - 24, tw + 16, 16);
    ctx.strokeStyle = 'rgba(255,180,84,0.35)';
    ctx.strokeRect(lx - 8, y - 24, tw + 16, 16);
    ctx.fillStyle = 'rgba(255,196,120,0.95)';
    ctx.fillText(label, lx, y - 12);
    ctx.font = '500 8px ui-monospace, SFMono-Regular, Menlo, monospace';
    ctx.fillStyle = 'rgba(255,170,90,0.55)';
    ctx.fillText('SAFE TO HOLD BELOW', lx, y + 30);

    // chevrons pointing down
    ctx.strokeStyle = 'rgba(255,180,84,0.4)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 5; i++) {
      const cx = (i + 0.5) * (W / 5) + Math.sin(t + i) * 3;
      ctx.beginPath();
      ctx.moveTo(cx - 4, y + 7);
      ctx.lineTo(cx, y + 11);
      ctx.lineTo(cx + 4, y + 7);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawScreenVignette(depth, bends) {
    const { W, H, ctx } = this;
    const v = ctx.createRadialGradient(W * 0.5, H * 0.48, Math.min(W, H) * 0.25, W * 0.5, H * 0.5, Math.max(W, H) * 0.78);
    v.addColorStop(0, 'rgba(0,0,0,0)');
    v.addColorStop(0.7, 'rgba(0,4,8,0.2)');
    v.addColorStop(1, 'rgba(0,2,5,0.72)');
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, W, H);

    // faint deep blue top gradient
    if (depth > 180) {
      const g = ctx.createLinearGradient(0, 0, 0, H * 0.35);
      g.addColorStop(0, `rgba(20,90,140,${0.03 + (depth - 180) / 6000})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H * 0.35);
    }
  }

  drawDepthRuler(run) {
    const { ctx, W, H } = this;
    const x = W - 18;
    const top = 120;
    const bottom = H - 150;
    if (bottom - top < 120) return;
    const meters = (bottom - top) / this.scale;
    const start = this.camY - meters / 2;
    ctx.save();
    ctx.globalAlpha = 0.55;
    ctx.strokeStyle = 'rgba(150,230,250,0.2)';
    ctx.fillStyle = 'rgba(160,235,250,0.42)';
    ctx.font = '7px ui-monospace, SFMono-Regular, monospace';
    ctx.textAlign = 'right';
    ctx.lineWidth = 1;
    for (let m = Math.ceil(start / 10) * 10; m < start + meters; m += 10) {
      if (m < 0 || m > WORLD.floor) continue;
      const y = top + ((m - start) / meters) * (bottom - top);
      const major = m % 50 === 0;
      ctx.beginPath();
      ctx.moveTo(x - (major ? 9 : 4), y);
      ctx.lineTo(x, y);
      ctx.stroke();
      if (major) ctx.fillText(String(m), x - 12, y + 2.4);
    }
    // current depth marker
    const dy = top + ((run.depth - start) / meters) * (bottom - top);
    if (dy > top - 4 && dy < bottom + 4) {
      ctx.globalAlpha = 0.9;
      ctx.fillStyle = '#7defff';
      ctx.beginPath();
      ctx.moveTo(x + 1, dy);
      ctx.lineTo(x - 6, dy - 4);
      ctx.lineTo(x - 6, dy + 4);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  drawOffscreenMarkers(run, t) {
    if (!run) return;
    const { ctx, W, H } = this;
    const x = this.mapX(run.x);
    const y = this.mapY(run.depth);
    const items = [];
    for (const c of run.canisters) {
      if (c.taken) continue;
      const dy = c.depth - run.depth;
      if (Math.abs(dy) < 34 && (Math.abs(c.x - run.x) > this.visW / 2 - 3)) items.push({ x: c.x, depth: c.depth, col: '90,255,225', kind: 'air' });
    }
    for (const it of run.items) {
      if (!it.special || it.taken) continue;
      items.push({ x: it.x, depth: it.depth, col: '255,160,85', kind: 'box' });
    }
    for (const m of items) {
      const mx = this.mapX(m.x);
      const my = this.mapY(m.depth);
      if (mx > 12 && mx < W - 12 && my > 20 && my < H - 20) continue;
      const edge = mx < 12 ? 18 : mx > W - 12 ? W - 18 : clamp(mx, 18, W - 18);
      const ey = clamp(my, 44, H - 44);
      const ang = Math.atan2(my - ey, mx - edge);
      ctx.save();
      ctx.translate(edge, ey);
      ctx.rotate(ang);
      ctx.fillStyle = `rgba(${m.col},${0.5 + Math.sin(t * 3) * 0.2})`;
      ctx.beginPath();
      ctx.moveTo(7, 0);
      ctx.lineTo(-4, -5);
      ctx.lineTo(-4, 5);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
      const d = Math.round(Math.hypot(m.x - run.x, m.depth - run.depth));
      ctx.save();
      ctx.font = '7px ui-monospace, monospace';
      ctx.fillStyle = `rgba(${m.col},0.6)`;
      ctx.textAlign = 'center';
      ctx.fillText(`${d}M`, edge, ey + 14);
      ctx.restore();
    }
  }

  drawPickupTexts(run, t) {
    const { ctx } = this;
    for (const txt of run.texts) {
      const x = this.mapX(txt.x);
      const y = this.mapY(txt.depth);
      const a = clamp(txt.life / 1.4, 0, 1);
      ctx.save();
      ctx.font = '600 13px ui-monospace, SFMono-Regular, Menlo, monospace';
      ctx.textAlign = 'center';
      ctx.fillStyle = `rgba(255,220,150,${a})`;
      ctx.shadowColor = 'rgba(255,180,90,0.8)';
      ctx.shadowBlur = 10;
      ctx.fillText(txt.text, x, y);
      ctx.restore();
    }
  }

  drawBendsBubbles(run, t) {
    const { ctx, W, H } = this;
    if (run.bends < 8 && !run.aboveCeiling) return;
    const intensity = clamp(run.bends / 100 + (run.aboveCeiling ? 0.2 : 0), 0, 1);
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 18; i++) {
      const seed = i * 17.3;
      const x = ((Math.sin(seed) * 0.5 + 0.5) * W + t * (8 + i * 2)) % W;
      const y = H - ((t * (20 + i * 3) + seed * 20) % H);
      const r = 1 + (i % 4) * 1.4;
      ctx.strokeStyle = `rgba(255,120,120,${0.06 + intensity * 0.12})`;
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, TAU);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawCurrents(run, t) {
    if (!run || !run.currents.length) return;
    const { ctx, W, H } = this;
    for (const c of run.currents) {
      const y0 = this.mapY(c.depth - c.width / 2);
      const y1 = this.mapY(c.depth + c.width / 2);
      if (y1 < 0 || y0 > H) continue;
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      for (let i = 0; i < 26; i++) {
        const seed = (i * 37 + this.currentSeed) % 100;
        const ph = ((t * 0.13 * (0.6 + (seed % 5) / 6) + seed / 100) % 1.25) - 0.12;
        const x = c.force > 0 ? ph * W : (1 - ph) * W;
        const y = y0 + ((seed * 7.1) % Math.max(1, y1 - y0));
        const len = 18 + (seed % 5) * 14;
        const a = 0.03 + (seed % 3) * 0.012;
        const g = ctx.createLinearGradient(x, y, x + Math.sign(c.force) * len, y);
        g.addColorStop(0, `rgba(140,235,250,${a})`);
        g.addColorStop(1, 'rgba(140,235,250,0)');
        ctx.strokeStyle = g;
        ctx.lineWidth = 0.8;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.sign(c.force) * len, y);
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  // ============================================================
  // PUBLIC
  // ============================================================
  renderDive(run, t) {
    this.time = t;
    const { ctx, W, H } = this;
    this._setCam(run.camera);
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    this.drawBackdrop(this.camY, t);
    this.drawSky(t);
    this.drawRays(this.camY, t);
    this.drawCliffs(this.camY);
    this.drawKelp(this.camY, t);
    this.drawSeabed(this.camY, t);
    this.drawWreck(this.camY, t, run.contract?.special);

    // fish behind
    for (const f of run.fish) this.drawFish(f, t);
    this.drawVents(run, t);

    // items
    for (const it of run.items) this.drawLoot(it, t);
    if (!run.freeDive) {
      for (const it of run.items) if (it.special) this.drawLoot(it, t);
    }
    for (const c of run.canisters) this.drawCanister(c, t);
    for (const j of run.jellies) this.drawJelly(j, t);

    // bubbles and particles (behind diver)
    for (const p of run.particles) this.drawParticle(p, t);
    this.drawCurrents(run, t);
    for (const b of run.bubbles) {
      const x = this.mapX(b.x);
      const y = this.mapY(b.depth);
      ctx.strokeStyle = `rgba(170,240,255,${0.25 * Math.min(1, b.life)})`;
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.arc(x, y, Math.max(0.6, b.r * this.scale * 0.5), 0, TAU);
      ctx.stroke();
    }

    // diver
    this.drawDiver(run, t, { x: run.x, depth: run.depth }, { vx: run.vx, vy: run.vy });

    // pickup texts
    this.drawPickupTexts(run, t);

    // darkness & lamp
    this.drawLighting(run, { x: run.x, depth: run.depth }, t);

    // glowing particles on top of darkness
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (const p of run.particles) {
      if (!p.glow) continue;
      const x = this.mapX(p.x);
      const y = this.mapY(p.depth);
      if (x < 0 || x > W || y < 0 || y > H) continue;
      const a = p.a * (0.55 + Math.sin(t * 2 + p.x) * 0.3);
      ctx.fillStyle = `rgba(120,255,240,${a * 0.35})`;
      ctx.fillRect(x - 1, y - 1, 2, 2);
    }
    ctx.restore();

    this.drawCeiling(run, t);
    this.drawOffscreenMarkers(run, t);
    this.drawDepthRuler(run);
    this.drawBendsBubbles(run, t);
    this.drawScreenVignette(run.depth, run.bends);

    if (run.flash > 0) {
      ctx.fillStyle = `rgba(160,240,255,${run.flash * 0.18})`;
      ctx.fillRect(0, 0, W, H);
    }
    if (run.aboveCeiling) {
      ctx.fillStyle = `rgba(255,40,35,${0.02 + Math.min(0.08, (run.ceiling - run.depth) * 0.002)})`;
      ctx.fillRect(0, 0, W, H);
    }
  }

  drawParticle(p, t) {
    const { ctx } = this;
    const x = this.mapX(p.x);
    const y = this.mapY(p.depth);
    if (x < -4 || x > this.W + 4 || y < -4 || y > this.H + 4) return;
    const tw = 0.6 + Math.sin(t * 1.5 + p.x * 3) * 0.4;
    ctx.fillStyle = `rgba(190,235,245,${p.a * 0.5 * tw})`;
    ctx.beginPath();
    ctx.arc(x, y, Math.max(0.4, p.r * this.scale), 0, TAU);
    ctx.fill();
  }

  renderTitle(t) {
    const { ctx, W, H } = this;
    this._setCam({ x: 66, y: 31 });
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    this.drawBackdrop(this.camY, t);
    this.drawSky(t);
    this.drawRays(this.camY, t);
    this.drawCliffs(this.camY);
    this.drawKelp(this.camY, t);
    this.drawSeabed(this.camY, t);
    this.drawWreck(this.camY, t, true);

    // fish school
    for (let i = 0; i < 22; i++) {
      const ph = i * 1.7;
      const f = {
        x: ((i * 13 + t * (2.2 + (i % 3) * 0.5)) % 150) - 15,
        depth: 26 + Math.sin(ph) * 16 + (i % 4) * 4,
        speed: 1,
        size: 0.5 + (i % 4) * 0.18,
        phase: ph,
        wobble: 1,
        deep: false,
      };
      this.drawFish(f, t);
    }
    // far fish
    for (let i = 0; i < 5; i++) {
      const f = {
        x: 20 + i * 18,
        depth: 50 + i * 7,
        speed: -1,
        size: 1.2,
        phase: i,
        wobble: 0.6,
        deep: true,
      };
      this.drawFish(f, t);
    }

    // particles
    const rnd = mulberry32(99);
    ctx.save();
    for (let i = 0; i < 70; i++) {
      const px = rnd() * W;
      const py = ((rnd() * H + t * (6 + (i % 4) * 3)) % (H + 20)) - 10;
      const a = 0.1 + rnd() * 0.35;
      ctx.fillStyle = `rgba(190,235,245,${a})`;
      ctx.beginPath();
      ctx.arc(px, py, 0.6 + rnd(), 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // demo diver
    const dive = {
      x: 84 + Math.sin(t * 0.12) * 3,
      depth: 34 + Math.sin(t * 0.2) * 4,
      vx: Math.cos(t * 0.12) * 0.4,
      vy: Math.cos(t * 0.2) * 0.8,
      invuln: 0,
      gear: { lamp: 20 },
    };
    // gentle bubbles
    this.drawDiver(dive, t, { x: dive.x, depth: dive.depth }, { vx: dive.vx, vy: dive.vy, idleAngle: 0.35 });

    // lighting anchored on diver (less dark for the title)
    const lc = this.lctx;
    lc.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    lc.clearRect(0, 0, W, H);
    lc.fillStyle = 'rgba(0,3,8,0.2)';
    lc.fillRect(0, 0, W, H);
    lc.globalCompositeOperation = 'destination-out';
    const dx = this.mapX(dive.x);
    const dy = this.mapY(dive.depth);
    const lamp = 20 * this.scale * 1.35;
    const g = lc.createRadialGradient(dx, dy, 0, dx, dy, lamp);
    g.addColorStop(0, 'rgba(0,0,0,0.9)');
    g.addColorStop(0.5, 'rgba(0,0,0,0.55)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    lc.fillStyle = g;
    lc.beginPath();
    lc.arc(dx, dy, lamp, 0, TAU);
    lc.fill();
    lc.globalCompositeOperation = 'source-over';
    lc.setTransform(1, 0, 0, 1, 0, 0);
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.drawImage(this.light, 0, 0);
    ctx.restore();

    this.drawScreenVignette(30, 0);

    // bottom haze so the title text reads
    const hz = ctx.createLinearGradient(0, 0, W * 0.68, 0);
    hz.addColorStop(0, 'rgba(1,7,12,0.7)');
    hz.addColorStop(0.7, 'rgba(1,7,12,0.18)');
    hz.addColorStop(1, 'rgba(1,7,12,0)');
    ctx.fillStyle = hz;
    ctx.fillRect(0, 0, W, H);
  }
}

const H_UNUSED = 0;

// ============================================================
// DECOMP — app shell, UI, loop
// ============================================================

import {
  WORLD, CONTRACTS, UPGRADES, DEFAULT_UPGRADES,
  createRun, updateRun, gearStats, upgradeCost, surfaceOutcome,
} from './world.js';
import { Renderer } from './render.js';
import { Sound } from './audio.js';

const SAVE_KEY = 'decomp.save.v1';
const $ = (id) => document.getElementById(id);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

const DEFAULT_SAVE = {
  contract: 0,
  completed: 0,
  money: 0,
  totalEarned: 0,
  bestDepth: 0,
  bestCargo: 0,
  upgrades: { ...DEFAULT_UPGRADES },
  muted: false,
  dives: 0,
};

function loadSave() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return structuredClone(DEFAULT_SAVE);
    const s = JSON.parse(raw);
    return {
      ...structuredClone(DEFAULT_SAVE),
      ...s,
      upgrades: { ...DEFAULT_UPGRADES, ...(s.upgrades || {}) },
    };
  } catch {
    return structuredClone(DEFAULT_SAVE);
  }
}

let save = loadSave();
const sound = new Sound();
sound.muted = !!save.muted;

let renderer;
let run = null;
let state = 'title';
let paused = false;
let shopReturn = 'brief';
let lastTime = performance.now();
let clock = 0;
let input = { x: 0, y: 0, boost: false };
let keys = new Set();
let touchActive = false;
let stick = { active: false, pointerId: null, x: 0, y: 0 };
let toastId = 0;
let lastAlarm = 0;
let lastUi = {};
let flashAmount = 0;
let diveStartMoney = 0;
let endingData = null;

const isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;

// ============================================================
// SAVE
// ============================================================
function persist() {
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(save)); } catch {}
}
function hasProgress() {
  return save.completed > 0 || save.money > 0 || save.totalEarned > 0 || Object.values(save.upgrades).some(Boolean);
}
function resetSave() {
  save = structuredClone(DEFAULT_SAVE);
  persist();
  renderTitleStats();
  updateMuteUI();
}

// ============================================================
// SCREENS
// ============================================================
const screens = ['titleScreen', 'howScreen', 'briefScreen', 'shopScreen', 'endScreen', 'pauseScreen'];
function hideScreens() { for (const id of screens) $(id).classList.add('hidden'); }
function showScreen(id) {
  for (const s of screens) $(s).classList.toggle('hidden', s !== id);
}
function setHudVisible(v) {
  $('hud').classList.toggle('hidden', !v);
  if (v && isTouch) $('touchControls').classList.remove('hidden');
  if (!v) $('touchControls').classList.add('hidden');
}

// ============================================================
// TITLE
// ============================================================
function renderTitleStats() {
  const best = save.bestDepth > 0 ? `${Math.round(save.bestDepth)} M` : '—';
  $('titleBest').textContent = best;
  $('titleEarned').textContent = `$${save.totalEarned.toLocaleString()}`;
  $('titleContracts').textContent = `${Math.min(4, save.completed)} / 4`;
  $('resetBtn').classList.toggle('hidden', !hasProgress());
  const done = save.completed >= CONTRACTS.length;
  $('startBtn').textContent = done ? 'FREE DIVE' : 'BEGIN CONTRACT';
}

function openTitle() {
  state = 'title';
  paused = false;
  hideScreens();
  showScreen('titleScreen');
  setHudVisible(false);
  renderTitleStats();
  run = null;
}

function openBriefing() {
  if (save.completed >= CONTRACTS.length) {
    startFreeDive();
    return;
  }
  const c = CONTRACTS[save.contract];
  state = 'briefing';
  hideScreens();
  showScreen('briefScreen');
  setHudVisible(false);
  renderer?.resize();

  $('briefCode').textContent = `CONTRACT ${c.code} / 04`;
  $('briefDivision').textContent = c.division;
  $('briefName').textContent = c.name;
  $('briefDesc').textContent = c.desc;
  $('briefDepth').textContent = `${c.depth} M`;
  $('briefQuota').textContent = `$${c.quota.toLocaleString()}`;
  $('briefBonus').textContent = `$${c.bonus.toLocaleString()}`;
  $('briefSpecial').classList.toggle('hidden', !c.special);

  const g = gearStats(save.upgrades);
  $('gearTank').textContent = `${g.maxAir} AIR`;
  $('gearLamp').textContent = `${g.lamp} M`;
  $('gearFins').textContent = `${Math.round(g.speed * 100)}%`;
  $('gearSuit').textContent = `N₂ ${Math.round(g.absorb * 100)}%`;
  $('briefTip').innerHTML = save.completed === 0
    ? '<span class="key">W</span><span class="key">S</span> to swim · hold at the amber ceiling to off-gas'
    : '<span class="key">SPACE</span> boost · watch your N₂ ceiling on the way up';
}

// ============================================================
// DIVE LIFECYCLE
// ============================================================
function startDive(freeDive = false) {
  sound.init();
  const idx = freeDive ? CONTRACTS.length - 1 : save.contract;
  run = createRun(idx, save.upgrades, { freeDive });
  if (freeDive) {
    run.quota = 0;
    run.special = false;
    run.specialDone = true;
    run.cargo = 0;
  }
  run.bestDepth = save.bestDepth;
  state = 'dive';
  paused = false;
  diveStartMoney = save.money;
  lastAlarm = 0;
  input = { x: 0, y: 0, boost: false };
  keys.clear();
  hideScreens();
  setHudVisible(true);
  renderer.resize();
  updateHud(true);
  addToast(freeDive ? 'FREE DIVE — NO QUOTA. GO DEEP.' : `CONTRACT ${run.contract.code} — ${run.contract.name}`, 'good', 3.2);
  setTimeout(() => {
    if (state === 'dive') addToast('COLLECT SALVAGE · RETURN BEFORE AIR RUNS OUT', '', 3.4);
  }, 900);
}

function startFreeDive() {
  openTitle();
  startDive(true);
}

function togglePause(force) {
  if (state !== 'dive' && state !== 'paused') return;
  const want = force !== undefined ? force : state === 'dive';
  if (want && state === 'dive') {
    state = 'paused';
    paused = true;
    $('pauseSub').textContent = `DEPTH ${Math.round(run.depth)} M · ${Math.round(run.air)} AIR · N₂ ${Math.round(run.n2)}% · $${run.cargo.toLocaleString()} CARGO`;
    showScreen('pauseScreen');
    setHudVisible(false);
    input = { x: 0, y: 0, boost: false };
  } else if (!want && state === 'paused') {
    state = 'dive';
    paused = false;
    hideScreens();
    setHudVisible(true);
    lastTime = performance.now();
  }
}

function finishDive(trigger) {
  if (!run || state === 'end') return;
  const out = surfaceOutcome(run);
  const n2Debt = run.ceiling > 1.8 || run.n2 > 8.5;
  const bendsBad = run.bends >= 35;
  let success = false;
  let cause = '';

  if (trigger === 'surface') {
    if (n2Debt) cause = 'SURFACED WITH N₂ DEBT';
    else if (bendsBad) cause = 'DECOMPRESSION SICKNESS';
    else if (!out.ok) cause = 'QUOTA NOT MET';
    else success = true;
  } else if (trigger === 'outOfAir') {
    cause = 'OUT OF AIR';
  } else if (trigger === 'bends') {
    cause = 'DECOMPRESSION SICKNESS';
  } else {
    cause = 'DIVE ABANDONED';
  }

  const stats = {
    cause,
    depth: run.peakDepth,
    cargo: run.cargo,
    quota: run.quota,
    time: run.timeAlive,
    pickups: run.pickups,
    special: run.specialDone,
    freeDive: run.freeDive,
    contractIndex: run.contractIndex,
    bends: run.bends,
    air: run.air,
  };

  state = 'end';
  setHudVisible(false);
  hideScreens();
  showScreen('endScreen');

  if (success) {
    const bonus = run.freeDive ? 0 : run.contract.bonus;
    const earnings = run.cargo + bonus;
    save.money += earnings;
    save.totalEarned += earnings;
    save.bestDepth = Math.max(save.bestDepth, run.peakDepth);
    save.bestCargo = Math.max(save.bestCargo, run.cargo);
    save.dives++;
    if (!run.freeDive) {
      save.completed = Math.max(save.completed, run.contractIndex + 1);
      save.contract = Math.min(CONTRACTS.length - 1, run.contractIndex + 1);
    }
    persist();
    renderTitleStats();
    endingData = { ...stats, earnings, bonus, success: true };
    showEndScreen(endingData, 'success');
    sound.success();
  } else {
    save.dives++;
    persist();
    renderTitleStats();
    endingData = { ...stats, success: false };
    showEndScreen(endingData, 'fail');
    sound.fail();
  }
}

// ============================================================
// END SCREEN
// ============================================================
function showEndScreen(data, kind) {
  const panel = $('endScreen').querySelector('.end-panel');
  panel.classList.remove('fail', 'win');
  const finalWin = kind === 'success' && !data.freeDive && data.contractIndex === CONTRACTS.length - 1;
  if (kind === 'fail') panel.classList.add('fail');
  if (finalWin) panel.classList.add('win');

  const statsHtml = [];
  if (kind === 'success') {
    $('endKicker').textContent = data.freeDive ? 'FREE DIVE COMPLETE' : 'CONTRACT COMPLETE';
    $('endTitle').textContent = finalWin ? 'TRENCH CLEARED' : (data.freeDive ? 'SURFACE' : 'CARGO BANKED');
    $('endSub').textContent = finalWin
      ? 'The black box is aboard. Four contracts, one trench, and a body that made it back. Free dive unlocked.'
      : (data.freeDive
        ? 'No quota, no contract. Just you, the dark, and whatever the trench gave up.'
        : 'The crew hauls you over the rail. Your cargo is weighed, banked, and the next contract waits.');
    statsHtml.push(
      `<div class="end-stat earn"><span class="eyebrow">SALVAGE</span><span>$${data.cargo.toLocaleString()}</span></div>`,
      `<div class="end-stat earn"><span class="eyebrow">CONTRACT BONUS</span><span>$${data.bonus.toLocaleString()}</span></div>`,
      `<div class="end-stat earn"><span class="eyebrow">BANKED</span><span>$${data.earnings.toLocaleString()}</span></div>`,
      `<div class="end-stat"><span class="eyebrow">MAX DEPTH</span><span>${Math.round(data.depth)} M</span></div>`,
      `<div class="end-stat"><span class="eyebrow">DIVE TIME</span><span>${fmtTime(data.time)}</span></div>`,
      `<div class="end-stat"><span class="eyebrow">RECOVERED</span><span>${data.pickups} ITEMS</span></div>`
    );
    $('endNextBtn').textContent = finalWin ? 'FREE DIVE' : 'EQUIPMENT';
    $('endNextBtn').classList.remove('hidden');
    $('endRetryBtn').classList.add('hidden');
    $('endTitleBtn').textContent = 'TITLE';
  } else {
    $('endKicker').textContent = 'DIVE LOST';
    $('endTitle').textContent = data.cause;
    $('endSub').textContent = data.cause === 'QUOTA NOT MET'
      ? 'You surfaced without the cargo to pay for the dive. The contract is still open.'
      : (data.cause === 'SURFACED WITH N₂ DEBT'
        ? 'You came up before your body was ready. The chamber is waiting; the cargo is not.'
        : (data.cause === 'OUT OF AIR'
          ? 'The tank ran dry in the dark. The crew marks the line and moves on.'
          : (data.cause === 'DIVE ABANDONED'
            ? 'You left the cargo on the bottom. No pay, no shame, no cargo.'
            : 'Nitrogen bubbles in the blood. The dive is over.')));
    statsHtml.push(
      `<div class="end-stat loss"><span class="eyebrow">CARGO LOST</span><span>$${data.cargo.toLocaleString()}</span></div>`,
      `<div class="end-stat"><span class="eyebrow">QUOTA</span><span>$${data.quota.toLocaleString()}</span></div>`,
      `<div class="end-stat"><span class="eyebrow">MAX DEPTH</span><span>${Math.round(data.depth)} M</span></div>`,
      `<div class="end-stat"><span class="eyebrow">DIVE TIME</span><span>${fmtTime(data.time)}</span></div>`,
      `<div class="end-stat"><span class="eyebrow">N₂ LOAD</span><span>${Math.round(run?.n2 || 0)}%</span></div>`,
      `<div class="end-stat"><span class="eyebrow">BENDS</span><span>${Math.round(data.bends)}%</span></div>`
    );
    $('endNextBtn').classList.add('hidden');
    $('endRetryBtn').classList.remove('hidden');
    $('endTitleBtn').textContent = 'TITLE';
  }
  $('endStats').innerHTML = statsHtml.join('');
}

// ============================================================
// SHOP
// ============================================================
const ICONS = {
  tank: `<svg viewBox="0 0 30 30" fill="none" stroke="currentColor" stroke-width="1.3"><rect x="9" y="7" width="12" height="18" rx="5"/><path d="M13 7V4h4v3M15 4V1M12 12h6M12 17h6"/></svg>`,
  lamp: `<svg viewBox="0 0 30 30" fill="none" stroke="currentColor" stroke-width="1.3"><path d="M8 11h9l5 4-5 4H8z"/><path d="M8 11V8h9v3M17 15l7-5v10l-7-5"/></svg>`,
  fins: `<svg viewBox="0 0 30 30" fill="none" stroke="currentColor" stroke-width="1.3"><path d="M9 6l4 8-1 9c3 2 8 0 9-3l-3-9-4-6z"/><path d="M4 12l5 2"/></svg>`,
  suit: `<svg viewBox="0 0 30 30" fill="none" stroke="currentColor" stroke-width="1.3"><path d="M10 6h10l3 5-2 3v10H9V14l-2-3z"/><path d="M12 6V3h6v3M12 14h6M15 14v10"/></svg>`,
  deco: `<svg viewBox="0 0 30 30" fill="none" stroke="currentColor" stroke-width="1.3"><circle cx="15" cy="12" r="6"/><path d="M15 6V2M15 22v6M9 12H3M27 12h-6M10 12l3 3M20 12l-3-3"/><circle cx="15" cy="12" r="2"/></svg>`,
};

function openShop(origin = 'brief') {
  shopReturn = origin;
  state = 'shop';
  hideScreens();
  showScreen('shopScreen');
  setHudVisible(false);
  renderShop();
}

function renderShop() {
  $('shopCash').textContent = `$${save.money.toLocaleString()}`;
  const grid = $('upgradeGrid');
  grid.innerHTML = UPGRADES.map((u) => {
    const lv = save.upgrades[u.id] || 0;
    const maxed = lv >= u.max;
    const cost = maxed ? 0 : upgradeCost(u, lv);
    const can = !maxed && save.money >= cost;
    const pips = Array.from({ length: u.max }, (_, i) => `<span class="pip ${i < lv ? 'on' : ''}"></span>`).join('');
    return `
      <div class="upgrade-card ${lv > 0 ? 'owned' : ''} ${maxed ? 'maxed' : ''}">
        <div class="upgrade-top">
          <div class="upgrade-icon" style="color:${maxed ? 'var(--green)' : 'var(--cyan)'}">${ICONS[u.icon]}</div>
          <div class="upgrade-name">${u.name}</div>
          <div class="upgrade-cost">${maxed ? 'MAX' : `$${cost.toLocaleString()}`}</div>
        </div>
        <div class="upgrade-pips">${pips}</div>
        <div class="upgrade-desc">${maxed ? u.effect(lv) : u.desc[lv]}</div>
        <button class="upgrade-buy ${maxed ? 'owned-label' : ''}" data-upg="${u.id}" ${(!can || maxed) ? 'disabled' : ''}>
          ${maxed ? 'FULLY UPGRADED' : (can ? `INSTALL — $${cost.toLocaleString()}` : `NEED $${cost.toLocaleString()}`)}
        </button>
      </div>`;
  }).join('');

  grid.querySelectorAll('[data-upg]').forEach((btn) => {
    btn.addEventListener('click', () => buyUpgrade(btn.dataset.upg));
  });
  $('shopNextBtn').textContent = shopReturn === 'afterSuccess' ? 'NEXT CONTRACT' : 'CONTINUE';
}

function buyUpgrade(id) {
  const u = UPGRADES.find((x) => x.id === id);
  if (!u) return;
  const lv = save.upgrades[id] || 0;
  if (lv >= u.max) return;
  const cost = upgradeCost(u, lv);
  if (save.money < cost) return;
  save.money -= cost;
  save.upgrades[id] = lv + 1;
  persist();
  sound.click();
  renderShop();
}

function shopContinue() {
  sound.click();
  if (shopReturn === 'afterSuccess') {
    if (save.completed >= CONTRACTS.length) openTitle();
    else openBriefing();
  } else if (shopReturn === 'brief') {
    openBriefing();
  } else {
    openTitle();
  }
}

// ============================================================
// HUD
// ============================================================
const setText = (id, val) => {
  const el = $(id);
  if (el.textContent !== String(val)) el.textContent = val;
};

function updateHud(force = false) {
  if (!run || (state !== 'dive' && state !== 'paused')) return;
  const d = Math.round(run.depth);
  setText('depthVal', String(d).padStart(3, '0'));
  setText('pressureVal', `${(1 + run.depth / 10).toFixed(1)} ATM`);
  setText('timeVal', fmtTime(run.timeAlive));
  setText('contractCode', run.freeDive ? 'FREE DIVE' : `CONTRACT ${run.contract.code}`);
  setText('contractName', run.freeDive ? 'NO QUOTA' : run.contract.name);
  setText('cashVal', `$${save.money.toLocaleString()}`);

  const quota = Math.max(1, run.quota);
  const pct = run.freeDive ? 100 : clamp((run.cargo / quota) * 100, 0, 100);
  const qf = $('quotaFill');
  qf.style.width = `${pct}%`;
  setText('quotaText', run.freeDive ? `$${run.cargo.toLocaleString()} RECOVERED` : `$${run.cargo.toLocaleString()} / $${run.quota.toLocaleString()}`);

  let obj = 'RECOVER SALVAGE — RETURN TO THE SURFACE';
  let priority = false;
  if (!run.freeDive) {
    if (run.special && !run.specialDone) {
      obj = 'PRIORITY: BLACK BOX AT 288 M';
      priority = true;
    } else if (run.quotaMet) {
      obj = 'QUOTA MET — CLEAR YOUR CEILING AND SURFACE';
    } else {
      obj = `RECOVER $${(run.quota - run.cargo).toLocaleString()} MORE SALVAGE`;
    }
  }
  setText('objectiveRow', obj);
  $('objectiveRow').classList.toggle('priority', priority);

  const air = Math.round(run.air);
  setText('airVal', `${air}`);
  $('airFill').style.width = `${clamp((run.air / run.maxAir) * 100, 0, 100)}%`;
  $('airGauge').classList.toggle('low', run.air < run.maxAir * 0.32 && run.air >= run.maxAir * 0.16);
  $('airGauge').classList.toggle('critical', run.air < run.maxAir * 0.16);

  setText('n2Val', `${Math.round(run.n2)}%`);
  $('n2Fill').style.width = `${clamp(run.n2, 0, 100)}%`;
  $('n2Gauge').classList.toggle('danger', run.n2 > 55 || run.aboveCeiling);
  setText('ceilingVal', run.ceiling > 0.6 ? `CEILING ${Math.round(run.ceiling)} M` : 'CEILING 0 M · SURFACE CLEAR');

  let deco = 'SAFE TO ASCEND';
  let cls = '';
  if (run.aboveCeiling) { deco = 'ABOVE CEILING — DESCEND NOW'; cls = 'danger'; }
  else if (run.offgassing && run.n2 > 7.5) { deco = 'OFF-GASSING — HOLD STEADY'; cls = 'offgas'; }
  else if (run.ongassing && run.n2 > 9) { deco = 'ON-GASSING — DEPTH LOAD'; cls = 'warn'; }
  else if (run.vy < -0.6) { deco = 'ASCENDING — LOAD LOCKED'; cls = 'ascend'; }
  else if (run.ceiling <= 0.6) { deco = 'SURFACE CLEAR — ASCEND'; cls = 'offgas'; }
  setText('decoState', deco);
  $('decoState').className = `deco-state ${cls}`;

  // warnings
  const warns = [];
  if (run.aboveCeiling) warns.push({ t: `ABOVE CEILING — HOLD AT ${Math.ceil(run.ceiling)} M`, d: true });
  if (run.bends > 45) warns.push({ t: `BENDS ${Math.round(run.bends)}% — DESCEND BELOW CEILING`, d: true });
  if (run.air < run.maxAir * 0.16) warns.push({ t: `AIR CRITICAL — ${Math.round(run.air)} UNITS`, d: true });
  else if (run.air < run.maxAir * 0.3) warns.push({ t: 'AIR LOW — FIND A CANISTER' });
  if (run.depth < 2.2 && run.ceiling > 1.8) warns.push({ t: `N₂ DEBT — HOLD AT ${Math.ceil(run.ceiling)} M`, d: true });
  const wkey = warns.map((w) => w.t).join('|');
  if (force || lastUi.wkey !== wkey) {
    lastUi.wkey = wkey;
    $('warnings').innerHTML = warns.map((w) => `<div class="warning ${w.d ? 'danger' : ''}">${w.t}</div>`).join('');
  }

  // alarm sounds
  const now = performance.now();
  if ((run.aboveCeiling || run.air < run.maxAir * 0.1) && now - lastAlarm > 900) {
    lastAlarm = now;
    sound.alarm();
  }

  // surface prompt
  const atSurface = run.depth < 2.5;
  const sp = $('surfacePrompt');
  if (atSurface) {
    sp.classList.remove('hidden');
    const canSafe = run.ceiling <= 1.8 && run.n2 <= 8.5 && run.bends < 35;
    if (run.freeDive) {
      $('surfacePromptText').textContent = canSafe ? `SURFACE & BANK $${run.cargo.toLocaleString()}` : `N₂ DEBT — HOLD AT ${Math.ceil(run.ceiling)} M`;
      $('surfaceBtn').textContent = canSafe ? 'SURFACE' : 'SURFACE ANYWAY';
    } else if (run.special && !run.specialDone) {
      $('surfacePromptText').textContent = 'BLACK BOX NOT RECOVERED — KEEP DIVING';
      $('surfaceBtn').textContent = 'SURFACE ANYWAY';
    } else if (run.quotaMet) {
      $('surfacePromptText').textContent = canSafe ? 'QUOTA MET — SURFACE TO BANK' : `N₂ DEBT — HOLD AT ${Math.ceil(run.ceiling)} M`;
      $('surfaceBtn').textContent = canSafe ? 'SURFACE' : 'SURFACE ANYWAY';
    } else {
      $('surfacePromptText').textContent = 'QUOTA NOT MET — SURFACE TO ABORT';
      $('surfaceBtn').textContent = 'SURFACE ANYWAY';
    }
  } else {
    sp.classList.add('hidden');
  }

  // bends vignette
  const v = clamp((run.bends / 100) * 0.85 + (run.aboveCeiling ? 0.16 : 0), 0, 0.92);
  $('bendsVignette').style.opacity = v.toFixed(3);

  // flash
  if (flashAmount > 0) {
    flashAmount = Math.max(0, flashAmount - 0.03);
  }
  $('flash').style.opacity = flashAmount.toFixed(3);
}

function addToast(text, cls = '', life = 2.8) {
  const zone = $('toastZone');
  const el = document.createElement('div');
  el.className = `toast ${cls}`;
  el.dataset.id = String(++toastId);
  el.textContent = text;
  zone.appendChild(el);
  while (zone.children.length > 4) zone.firstChild.remove();
  setTimeout(() => {
    el.style.transition = 'opacity .3s, transform .3s';
    el.style.opacity = '0';
    el.style.transform = 'translateX(8px)';
    setTimeout(() => el.remove(), 320);
  }, life * 1000);
}

function handleEvents(events) {
  for (const e of events) {
    if (e.type === 'loot') {
      run.texts.push({ x: e.x, depth: e.depth, text: `+$${e.value.toLocaleString()}`, life: 1.5 });
      sound.collect(e.value);
      addToast(`SALVAGE +$${e.value.toLocaleString()}`, 'good', 1.9);
    } else if (e.type === 'air') {
      sound.air();
      run.texts.push({ x: e.x, depth: e.depth, text: `AIR +${e.amount}`, life: 1.5, color: 'teal' });
      addToast(`AIR CANISTER +${e.amount}`, 'good', 1.9);
    } else if (e.type === 'sting') {
      sound.sting();
      flashAmount = 0.85;
      $('flash').style.opacity = '0.85';
      run.texts.push({ x: e.x, depth: e.depth, text: 'STING', life: 1.2 });
      addToast('JELLYFISH STING — AIR −7 · N₂ +7', 'bad', 2.4);
    } else if (e.type === 'blackbox') {
      sound.blackbox();
      flashAmount = 1;
      run.texts.push({ x: e.x, depth: e.depth, text: 'BLACK BOX +$1,600', life: 2.4 });
      addToast('BLACK BOX RECOVERED — SURFACE WHEN CLEAR', 'good', 4);
    } else if (e.type === 'death') {
      finishDive(e.cause === 'OUT OF AIR' ? 'outOfAir' : 'bends');
      return;
    }
  }
  if (run?.dead) {
    if (run.deathCause === 'OUT OF AIR') finishDive('outOfAir');
    else finishDive('bends');
  }
}

function fmtTime(sec) {
  const s = Math.max(0, Math.floor(sec));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

// ============================================================
// INPUT
// ============================================================
const keyMap = {
  w: 'up', arrowup: 'up',
  s: 'down', arrowdown: 'down',
  a: 'left', arrowleft: 'left',
  d: 'right', arrowright: 'right',
  ' ': 'boost', space: 'boost',
};

function updateInputFromKeys() {
  let x = 0; let y = 0;
  if (keys.has('left')) x -= 1;
  if (keys.has('right')) x += 1;
  if (keys.has('up')) y -= 1;
  if (keys.has('down')) y += 1;
  input.x = x;
  input.y = y;
  input.boost = keys.has('boost');
}

window.addEventListener('keydown', (e) => {
  const k = e.key.toLowerCase();
  if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) {
    if (state === 'dive') e.preventDefault();
  }
  if (k === 'escape' || k === 'p') {
    if (state === 'dive' || state === 'paused') { togglePause(); e.preventDefault(); }
    return;
  }
  if (k === 'm') { toggleMute(); return; }
  if (k === 'e' || k === 'enter') {
    if (state === 'dive' && run.depth < 2.5) { finishDive('surface'); }
    return;
  }
  const mapped = keyMap[k];
  if (mapped) {
    keys.add(mapped);
    updateInputFromKeys();
    if (state === 'dive' && e.repeat && mapped === 'boost') e.preventDefault();
  }
});

window.addEventListener('keyup', (e) => {
  const k = e.key.toLowerCase();
  const mapped = keyMap[k];
  if (mapped) {
    keys.delete(mapped);
    updateInputFromKeys();
  }
});

window.addEventListener('blur', () => {
  keys.clear();
  updateInputFromKeys();
  if (state === 'dive') togglePause(true);
});

// ----- touch joystick -----
function setupTouch() {
  if (!isTouch) return;
  document.body.classList.add('touch');
  const base = $('stickBase');
  const knob = $('stickKnob');
  const radius = 44;
  let center = { x: 0, y: 0 };

  function start(e) {
    e.preventDefault();
    sound.init();
    stick.active = true;
    stick.pointerId = e.pointerId;
    const r = base.getBoundingClientRect();
    center = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    base.setPointerCapture?.(e.pointerId);
    move(e);
  }
  function move(e) {
    if (!stick.active || (stick.pointerId != null && e.pointerId !== stick.pointerId)) return;
    e.preventDefault();
    let dx = e.clientX - center.x;
    let dy = e.clientY - center.y;
    const d = Math.hypot(dx, dy);
    if (d > radius) { dx = (dx / d) * radius; dy = (dy / d) * radius; }
    knob.style.transform = `translate(${dx}px, ${dy}px)`;
    input.x = dx / radius;
    input.y = dy / radius;
  }
  function end(e) {
    if (stick.pointerId != null && e.pointerId !== stick.pointerId) return;
    stick.active = false;
    stick.pointerId = null;
    knob.style.transform = 'translate(0,0)';
    input.x = 0;
    input.y = 0;
  }
  base.addEventListener('pointerdown', start);
  base.addEventListener('pointermove', move);
  base.addEventListener('pointerup', end);
  base.addEventListener('pointercancel', end);
  base.addEventListener('lostpointercapture', end);

  const boost = $('boostBtn');
  boost.addEventListener('pointerdown', (e) => {
    e.preventDefault();
    sound.init();
    input.boost = true;
    boost.setPointerCapture?.(e.pointerId);
  });
  const bEnd = (e) => { e.preventDefault(); input.boost = false; };
  boost.addEventListener('pointerup', bEnd);
  boost.addEventListener('pointercancel', bEnd);
  boost.addEventListener('lostpointercapture', bEnd);

  // prevent page gestures on the play surface
  $('app').addEventListener('touchmove', (e) => {
    if (state === 'dive') e.preventDefault();
  }, { passive: false });
}

// ============================================================
// AUDIO UI
// ============================================================
function updateMuteUI() {
  const btn = $('muteBtn');
  const pbtn = $('pauseMuteBtn');
  btn.classList.toggle('muted', sound.muted);
  btn.textContent = sound.muted ? '✕' : '♪';
  pbtn.textContent = `SOUND: ${sound.muted ? 'OFF' : 'ON'}`;
  sound.setMuted(sound.muted);
}
function toggleMute() {
  sound.init();
  sound.muted = !sound.muted;
  save.muted = sound.muted;
  persist();
  updateMuteUI();
  sound.click();
}

// ============================================================
// MAIN LOOP
// ============================================================
function frame(now) {
  const dt = Math.min(0.05, Math.max(0, (now - lastTime) / 1000));
  lastTime = now;
  clock += dt;

  if (state === 'dive' && run) {
    run.time += 0; // keep sim dt explicit below
    const events = [];
    updateRun(run, dt, input, events);
    handleEvents(events);
    if (state === 'dive') {
      updateHud();
      for (const t of run.texts) {
        if (t.color === 'teal') t.text = t.text;
      }
      sound.update(dt, run.depth);
    }
  }

  // subtle idle camera drift for title
  if (state !== 'dive' && state !== 'paused' && state !== 'end') {
    if (run) run.camera.y = run.camera.y;
  }

  if (run && (state === 'dive' || state === 'paused' || state === 'end')) {
    renderer.renderDive(run, clock);
  } else {
    renderer.renderTitle(clock);
  }

  if (state === 'dive') {
    if (flashAmount > 0) {
      flashAmount = Math.max(0, flashAmount - dt * 2.2);
      $('flash').style.opacity = flashAmount.toFixed(3);
    }
    const v = clamp((run.bends / 100) * 0.85 + (run.aboveCeiling ? 0.16 : 0), 0, 0.92);
    $('bendsVignette').style.opacity = v.toFixed(3);
  } else {
    $('bendsVignette').style.opacity = '0';
  }

  requestAnimationFrame(frame);
}

// ============================================================
// WIRING
// ============================================================
function wire() {
  $('startBtn').addEventListener('click', () => {
    sound.init(); sound.click();
    if (save.completed >= CONTRACTS.length) startFreeDive();
    else openBriefing();
  });
  $('howBtn').addEventListener('click', () => { sound.init(); sound.click(); showScreen('howScreen'); });
  $('resetBtn').addEventListener('click', () => {
    if (confirm('Reset all dive progress, cash, and equipment?')) {
      resetSave(); sound.click();
    }
  });

  document.querySelectorAll('[data-close]').forEach((b) => {
    b.addEventListener('click', () => {
      sound.click();
      if (state === 'title') showScreen('titleScreen');
      else openBriefing();
    });
  });

  $('diveBtn').addEventListener('click', () => { sound.click(); startDive(); });
  $('briefShopBtn').addEventListener('click', () => { sound.init(); sound.click(); openShop('brief'); });
  $('briefBackBtn').addEventListener('click', () => { sound.click(); openTitle(); });

  $('shopNextBtn').addEventListener('click', shopContinue);
  $('shopResetBtn').addEventListener('click', () => {
    if (confirm('Reset all progress, cash, and equipment? This cannot be undone.')) {
      resetSave(); sound.click(); openTitle();
    }
  });

  $('pauseBtn').addEventListener('click', () => { sound.click(); togglePause(true); });
  $('muteBtn').addEventListener('click', toggleMute);
  $('resumeBtn').addEventListener('click', () => { sound.click(); togglePause(false); });
  $('pauseMuteBtn').addEventListener('click', toggleMute);
  $('restartBtn').addEventListener('click', () => {
    sound.click();
    if (!run) return;
    const free = run.freeDive;
    hideScreens();
    startDive(free);
  });
  $('quitBtn').addEventListener('click', () => {
    sound.click();
    if (run) finishDive('abandon');
  });

  $('surfaceBtn').addEventListener('click', () => {
    sound.click();
    finishDive('surface');
  });

  $('endNextBtn').addEventListener('click', () => {
    sound.click();
    if (!endingData) return;
    if (endingData.success && endingData.contractIndex === CONTRACTS.length - 1 && !endingData.freeDive) {
      startFreeDive();
    } else if (endingData.success) {
      openShop('afterSuccess');
    } else {
      openShop('afterSuccess');
    }
  });
  $('endRetryBtn').addEventListener('click', () => {
    sound.click();
    hideScreens();
    startDive(false);
  });
  $('endTitleBtn').addEventListener('click', () => { sound.click(); openTitle(); });
}

// ============================================================
// BOOT
// ============================================================
function boot() {
  renderer = new Renderer($('scene'));
  renderer.resize();
  wire();
  updateMuteUI();
  renderTitleStats();
  setupTouch();
  openTitle();
  requestAnimationFrame((t) => { lastTime = t; requestAnimationFrame(frame); });

  // rotate nudge on small portrait screens during dive
  const checkOrient = () => {
    const portrait = window.innerHeight > window.innerWidth && isTouch;
    $('rotateNudge').classList.toggle('hidden', !(portrait && state === 'dive'));
  };
  window.addEventListener('resize', checkOrient);
  setInterval(checkOrient, 1200);
}

// prevent iOS double-tap zoom
document.addEventListener('gesturestart', (e) => e.preventDefault());
boot();

