import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1000);
console.log('ERRORS:', errors);
console.log('state', await page.evaluate(() => ({ depth: document.getElementById('depthVal').textContent, title: getComputedStyle(document.getElementById('titleScreen')).display })));

// start
await page.click('#startBtn');
await page.waitForTimeout(400);
console.log('brief?', await page.isVisible('#briefScreen'));
await page.click('#diveBtn');
await page.waitForTimeout(600);
console.log('dive depth', await page.textContent('#depthVal'));

// descend 3 seconds
await page.keyboard.down('s');
await page.waitForTimeout(3000);
await page.keyboard.up('s');
await page.waitForTimeout(300);
