  depth: document.getElementById('depthVal').textContent,
  n2: document.getElementById('n2Val').textContent,
  air: document.getElementById('airVal').textContent,
  deco: document.getElementById('decoState').textContent,
})));
await page.screenshot({ path: 'screenshots/test-descend.jpg', type: 'jpeg', quality: 80 });

await browser.close();

