input.content:
import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(700);
console.log('ERRORS:', errors);
await page.click('#startBtn');
await page.waitForTimeout(300);
await page.click('#diveBtn');
await page.waitForTimeout(500);

async function state() {
  return page.evaluate(() => ({
    depth: document.getElementById('depthVal').textContent,
    n2: document.getElementById('n2Val').textContent,
    air: document.getElementById('airVal').textContent,
    cargo: document.getElementById('quotaText').textContent,
    deco: document.getElementById('decoState').textContent,
    ceil: document.getElementById('ceilingVal').textContent,
    prompt: !document.getElementById('surfacePrompt').classList.contains('hidden'),
  }));
}

await page.keyboard.down('s');
await page.waitForTimeout(4500);
await page.keyboard.up('s');
await page.waitForTimeout(400);
console.log('after 4.5s down:', await state());
await page.screenshot({ path: 'screenshots/test-40.jpg', type: 'jpeg', quality: 82 });

// move right and down for a while
await page.keyboard.down('d');
await page.waitForTimeout(1500);
await page.keyboard.up('d');
await page.keyboard.down('s');
await page.waitForTimeout(2500);
await page.keyboard.up('s');
await page.waitForTimeout(300);
console.log('after more down:', await state());
await page.screenshot({ path: 'screenshots/test-70.jpg', type: 'jpeg', quality: 82 });

// ascend
await page.keyboard.down('w');
await page.waitForTimeout(3000);
await page.keyboard.up('w');
await page.waitForTimeout(300);
console.log('after ascend 3s:', await state());
await page.screenshot({ path: 'screenshots/test-ascend.jpg', type: 'jpeg', quality: 82 });

console.log('prompt text', await page.textContent('#surfacePromptText'));
await browser.close();

