import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(400);
await page.click('#startBtn'); await page.waitForTimeout(200); await page.click('#diveBtn'); await page.waitForTimeout(300);
const st = () => page.evaluate(() => { const r = window.__DECOMP.run; return { d: +r.depth.toFixed(1), n2: +r.n2.toFixed(1), c: +(r.ceiling||0).toFixed(1), b: +r.bends.toFixed(1), off: r.offgassing, on: r.ongassing, above: r.aboveCeiling, air: +r.air.toFixed(1) }; });
await page.evaluate(() => { const r = window.__DECOMP.run; r.depth=200; r.x=60; r.vx=0; r.vy=0; r.n2=40; });
await page.waitForTimeout(150);
console.log('start', await st());
// hold in the band for 3s, re-centering every 150ms
for (let i=0;i<20;i++) {
  await page.evaluate(() => { const r=window.__DECOMP.run; r.depth = (r.ceiling||0) + 2; r.vy = 0; });
  await page.waitForTimeout(150);
}
console.log('held 3s', await st());
// above ceiling
await page.evaluate(() => { const r=window.__DECOMP.run; r.depth = (r.ceiling||0) - 15; r.vy=0; });
await page.waitForTimeout(1500);
console.log('above 1.5s', await st());
// hold in band again 2s
for (let i=0;i<14;i++) {
  await page.evaluate(() => { const r=window.__DECOMP.run; r.depth = (r.ceiling||0) + 2; r.vy = 0; r.bends = Math.max(0, r.bends); });
  await page.waitForTimeout(150);
}
console.log('band 2s', await st());
await page.screenshot({ path: 'screenshots/test-deco2.jpg', type: 'jpeg', quality: 82 });
await browser.close();
