281: export function updateRun(run, dt, input, events) {
282:   if (run.dead) return;
283:   const stats = run.gear;
284:   const contract = run.contract;
285:   run.time += dt;
286:   run.timeAlive += dt;
287: 
288:   // ---------- movement ----------
289:   let ix = input.x || 0;
290:   let iy = input.y || 0;
291:   const mag = Math.hypot(ix, iy);
292:   if (mag > 1) { ix /= mag; iy /= mag; }
293:   const boosting = !!input.boost && mag > 0.1 && run.air > 0 && run.depth > 0.9;
294:   const boostMul = boosting ? 1.42 : 1;
295: 
296:   const accel = 22 * stats.speed * boostMul;
297:   run.vx += ix * accel * dt;
298:   run.vy += iy * accel * dt;
299: 
300:   // gentle current push
301:   for (const c of run.currents) {
302:     if (Math.abs(run.depth - c.depth) < c.width / 2) {
303:       run.vx += c.force * dt * 1.25;
304:     }
305:   }
306: 
307:   // buoyancy: barely positive, keeps the diver floating when idle
308:   run.vy -= 0.12 * dt;
309: 
310:   const drag = Math.pow(0.08, dt); // ≈ exp(-2.53 dt)
311:   run.vx *= drag;
312:   run.vy *= drag;
313: 
314:   const maxV = 7.4 * stats.speed * boostMul;
315:   const sp = Math.hypot(run.vx, run.vy);
316:   if (sp > maxV) { run.vx = (run.vx / sp) * maxV; run.vy = (run.vy / sp) * maxV; }
317: 
318:   run.x += run.vx * dt;
319:   const oldDepth = run.depth;
320:   run.depth += run.vy * dt;
321: 
322:   // bounds
323:   if (run.x < 4) { run.x = 4; run.vx = Math.max(0, run.vx); }
324:   if (run.x > WORLD.width - 4) { run.x = WORLD.width - 4; run.vx = Math.min(0, run.vx); }
325:   if (run.depth < 0.8) {
326:     run.depth = 0.8;
327:     if (run.vy < 0) run.vy = 0;
328:     if (oldDepth > 2) events.push({ type: 'surface' });
329:   }
330:   if (run.depth > WORLD.floor - 2) {
331:     run.depth = WORLD.floor - 2;
332:     if (run.vy > 0) run.vy = 0;
333:   }
334: 
335:   run.ascentRate = (run.depth - oldDepth) / Math.max(dt, 0.0001); // negative = up
336:   run.peakDepth = Math.max(run.peakDepth, run.depth);
337:   run.atSurface = run.depth < 2.2;
338:   run.invuln = Math.max(0, run.invuln - dt);
339:   run.flash = Math.max(0, run.flash - dt * 3);
340: 
341:   // ---------- nitrogen model ----------
342:   // Ceiling = the shallowest depth the body can tolerate right now.
343:   const ceiling = Math.max(0, (run.n2 - 7) * 3.2);
344:   run.ceiling = ceiling;
345:   const depthAboveCeiling = ceilDelta(run.depth, ceiling);
346: 
347:   run.offgassing = false;
348:   run.ongassing = false;
349:   run.aboveCeiling = false;
350: 
351:   if (depthAboveCeiling > 5.5) {
352:     // deep enough to keep loading tissue
353:     if (run.depth > 6 && run.vy > -0.35) {
354:       const absorb = (0.38 + run.depth * 0.0042) * stats.absorb;
355:       run.n2 = clamp(run.n2 + absorb * dt, 0, 100);
356:       run.ongassing = true;
357:     }
358:   } else if (depthAboveCeiling >= -0.8 && run.depth > 0.9) {
359:     // in the off-gas band just below the ceiling
360:     const rate = 1.18 * stats.offgas;
361:     run.n2 = Math.max(0, run.n2 - rate * dt);
362:     run.offgassing = true;
363:   } else {
364:     // above the ceiling: bubbles form
365:     run.aboveCeiling = true;
366:     const over = ceiling - run.depth;
367:     run.bends = clamp(run.bends + over * 0.82 * dt, 0, 100);
368:     run.camera.shake = Math.max(run.camera.shake, Math.min(1, over / 25 + 0.2));
369:     events.push({ type: 'aboveCeiling', over });
370:   }
371:   if (!run.aboveCeiling) {
372:     run.bends = Math.max(0, run.bends - 1.15 * dt);
373:   }
374: 
375:   // ---------- air ----------
376:   if (run.depth > 0.9) {
377:     const speedRatio = Math.min(1, Math.hypot(run.vx, run.vy) / 6);
378:     let drain = (0.185 + run.depth * 0.00225) * (1 + 0.62 * speedRatio);
379:     if (boosting) drain *= 1.55;
380:     run.air = Math.max(0, run.air - drain * dt);
381:     if (run.air <= 0) {
382:       run.dead = true;
383:       run.deathCause = 'OUT OF AIR';
384:       events.push({ type: 'death', cause: 'OUT OF AIR' });
385:       return;
386:     }
387:     if (run.air < run.maxAir * 0.22 && !run.tips.lowAir) {
388:       run.tips.lowAir = true;
389:       events.push({ type: 'lowAir' });
390:     }
391:     if (run.air > run.maxAir * 0.3) run.tips.lowAir = false;
392:   }
393:   if (run.bends >= 100) {
394:     run.dead = true;
395:     run.deathCause = 'DECOMPRESSION SICKNESS';
396:     events.push({ type: 'death', cause: 'DECOMPRESSION SICKNESS' });
397:     return;
398:   }
399: 
400:   // ---------- pickups ----------
401:   for (const it of run.items) {
402:     if (it.taken) continue;
403:     it.bob += dt;
404:     const radius = it.kind === 'blackbox' ? 4.2 : 3.0;
405:     if (Math.abs(it.depth - run.depth) < radius && Math.abs(it.x - run.x) < radius + 0.6) {
406:       it.taken = true;
407:       run.pickups++;
408:       run.cargo += it.value;
409:       if (it.special) {
410:         run.specialDone = true;
411:         run.flash = 0.9;
412:         events.push({ type: 'blackbox', value: it.value, x: it.x, depth: it.depth });
413:       } else {
414:         events.push({ type: 'loot', value: it.value, x: it.x, depth: it.depth });
415:       }
416:       run.bubbles.push({ x: it.x, depth: it.depth, life: 0.8, r: 0.5, vy: -2 });
417:     }
418:   }
419: 
420:   for (const c of run.canisters) {
421:     if (c.taken) continue;
422:     c.phase += dt;
423:     if (Math.abs(c.depth - run.depth) < 3.2 && Math.abs(c.x - run.x) < 3.4) {
424:       c.taken = true;
425:       const before = run.air;
