630: // ----- touch joystick -----
631: function setupTouch() {
632:   if (!isTouch) return;
633:   document.body.classList.add('touch');
634:   const base = $('stickBase');
635:   const knob = $('stickKnob');
636:   const radius = 44;
637:   let center = { x: 0, y: 0 };
638: 
639:   function start(e) {
640:     e.preventDefault();
641:     sound.init();
642:     stick.active = true;
643:     stick.pointerId = e.pointerId;
644:     const r = base.getBoundingClientRect();
645:     center = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
646:     base.setPointerCapture?.(e.pointerId);
647:     move(e);
648:   }
649:   function move(e) {
650:     if (!stick.active || (stick.pointerId != null && e.pointerId !== stick.pointerId)) return;
651:     e.preventDefault();
652:     let dx = e.clientX - center.x;
653:     let dy = e.clientY - center.y;
654:     const d = Math.hypot(dx, dy);
655:     if (d > radius) { dx = (dx / d) * radius; dy = (dy / d) * radius; }
656:     knob.style.transform = `translate(${dx}px, ${dy}px)`;
657:     input.x = dx / radius;
658:     input.y = dy / radius;
659:   }
660:   function end(e) {
661:     if (stick.pointerId != null && e.pointerId !== stick.pointerId) return;
662:     stick.active = false;
663:     stick.pointerId = null;
664:     knob.style.transform = 'translate(0,0)';
665:     input.x = 0;
666:     input.y = 0;
667:   }
668:   base.addEventListener('pointerdown', start);
669:   base.addEventListener('pointermove', move);
670:   base.addEventListener('pointerup', end);
671:   base.addEventListener('pointercancel', end);
672:   base.addEventListener('lostpointercapture', end);
673: 
674:   const boost = $('boostBtn');
675:   boost.addEventListener('pointerdown', (e) => {
676:     e.preventDefault();
677:     sound.init();
678:     input.boost = true;
679:     boost.setPointerCapture?.(e.pointerId);
680:   });
681:   const bEnd = (e) => { e.preventDefault(); input.boost = false; };
682:   boost.addEventListener('pointerup', bEnd);
683:   boost.addEventListener('pointercancel', bEnd);
684:   boost.addEventListener('lostpointercapture', bEnd);
685: 
686:   // prevent page gestures on the play surface
687:   $('app').addEventListener('touchmove', (e) => {
688:     if (state === 'dive') e.preventDefault();
689:   }, { passive: false });
690: }
