import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const errors = [];
const browser = await chromium.launch({ headless: true });
const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
const page = await ctx.newPage();
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/e2e-title.jpg', type: 'jpeg', quality: 80 });

// briefing
await page.click('#startBtn');
await page.waitForTimeout(350);
console.log('brief visible:', await page.isVisible('#briefScreen'), '| name:', await page.textContent('#briefName'));
await page.screenshot({ path: 'screenshots/e2e-brief.jpg', type: 'jpeg', quality: 80 });

// dive
await page.click('#diveBtn');
await page.waitForTimeout(500);
const state = () => page.evaluate(() => window.__DECOMP.state);
const run = () => page.evaluate(() => {
  const r = window.__DECOMP.run;
  return { depth: +r.depth.toFixed(2), x: +r.x.toFixed(2), air: +r.air.toFixed(1), n2: +r.n2.toFixed(2), cargo: r.cargo, quota: r.quota, ceiling: +(r.ceiling || 0).toFixed(2), pickups: r.pickups };
});
console.log('state after dive:', await state(), await run());

// real keyboard controls
const d0 = (await run()).depth;
await page.keyboard.down('s'); await page.waitForTimeout(900); await page.keyboard.up('s');
await page.waitForTimeout(250);
const d1 = (await run()).depth;
await page.keyboard.down('w'); await page.waitForTimeout(700); await page.keyboard.up('w');
await page.waitForTimeout(250);
const d2 = (await run()).depth;
console.log('keyboard depth:', d0, '-> down', d1, '-> up', d2, '| PASS', d1 > d0 + 2 && d2 < d1 - 2);

// collect loot through normal pickup logic by lining up with items
for (let step = 0; step < 40; step++) {
  const done = await page.evaluate(() => {
    const r = window.__DECOMP.run;
    if (r.cargo >= r.quota) return true;
    const it = r.items.filter((i) => !i.taken).sort((a, b) => Math.hypot(a.x - r.x, a.depth - r.depth) - Math.hypot(b.x - r.x, b.depth - r.depth))[0];
    if (!it) return true;
    r.x = it.x; r.depth = it.depth; r.vx = 0; r.vy = 0;
